INSERT INTO `recipe` VALUES (101,'藜麦鸡胸能量碗','高蛋白、低负担的轻食主餐，适合减脂和塑形期。','午餐','轻食',20,'简单',1,403.4,403.4,45.7,36.8,7.6,5,'[\"藜麦煮熟备用\",\"鸡胸肉煎熟切片\",\"生菜和紫甘蓝洗净切丝\",\"将所有食材装碗后拌匀即可\"]','可加入少量黑胡椒提升风味。',NULL,NULL,0,4.8,0,0,0,'减脂人群、健身人群','减肥减脂',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (102,'三文鱼牛油果沙拉','富含优质脂肪与蛋白质，适合控脂和心血管友好型饮食。','晚餐','轻食',18,'简单',1,374.7,374.7,27,11.8,25.1,5.6,'[\"三文鱼煎熟切块\",\"牛油果切丁\",\"生菜和蓝莓洗净备用\",\"所有食材混合后即可食用\"]','控盐饮食可不加额外沙拉酱。',NULL,NULL,0,4.9,0,0,0,'控脂降脂、老年养生','控脂降脂',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (103,'无糖酸奶蓝莓燕麦杯','适合早餐和加餐的低糖高纤组合。','早餐','轻食',10,'简单',1,312.9,312.9,13.4,40.4,11.8,5,'[\"无糖酸奶倒入杯中\",\"加入燕麦\",\"放入蓝莓和少量坚果\",\"冷藏后口感更佳\"]','控糖人群可减少水果量。',NULL,NULL,0,4.7,0,0,0,'控糖饮食、维持体重','控糖饮食',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (104,'金枪鱼全麦三明治','高蛋白便捷早餐，适合上班族和塑形期。','早餐','西式',12,'简单',1,265.2,265.2,31,26.9,3.2,5,'[\"全麦面包烘热\",\"金枪鱼沥干后铺在面包上\",\"加入生菜和番茄片\",\"夹好后对半切开\"]','可搭配低脂牛奶食用。',NULL,NULL,0,4.8,0,0,0,'增肌塑形、维持体重','增肌塑形',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (105,'瘦牛肉藜麦饭','高蛋白主餐，适合增肌和健康增重。','午餐','中式',25,'中等',1,486,486,34.8,46.4,18.3,6.4,'[\"藜麦煮熟备用\",\"瘦牛肉切片快炒\",\"加入洋葱和西兰花翻炒\",\"与藜麦搭配装盘\"]','训练日可适当增加藜麦分量。',NULL,NULL,0,4.9,0,0,1,'增肌塑形、健康增重','健康增重',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (106,'南瓜小米粥','温和易消化，适合老年养生和胃口较弱人群。','早餐','中式',30,'简单',1,136.8,136.8,4.2,28.9,1.1,0.8,'[\"南瓜去皮切块\",\"小米淘洗干净\",\"加入适量清水熬煮\",\"煮至软糯即可\"]','可作为清淡早餐主食。',NULL,NULL,0,4.6,0,0,0,'老年养生、控脂降脂','老年养生',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (107,'冬瓜虾仁汤','低热量高蛋白汤品，适合作为晚餐配菜或控脂餐。','晚餐','中式',15,'简单',1,92.4,92.4,19.7,3.3,0.5,0.8,'[\"冬瓜切片\",\"虾仁焯水备用\",\"锅中加水煮开后放入冬瓜\",\"加入虾仁煮熟调味即可\"]','控压饮食注意减少盐用量。',NULL,NULL,0,4.7,0,0,0,'控压低盐、减肥减脂','控压低盐',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (108,'芦笋鸡蛋卷','营养均衡、制作快捷，适合作为早餐或加餐。','早餐','中式',10,'简单',1,171,171,14.8,4.2,10.7,1.7,'[\"鸡蛋打散\",\"芦笋焯水切段\",\"平底锅煎蛋皮\",\"卷入芦笋后切段装盘\"]','可搭配低脂牛奶增强饱腹感。',NULL,NULL,0,4.6,0,0,0,'儿童成长、维持体重','儿童成长',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (109,'黑豆豆腐营养碗','植物蛋白丰富，适合素食和控脂人群。','午餐','轻食',22,'中等',1,385.4,385.4,28.3,56.9,7.1,14.3,'[\"黑豆提前煮熟\",\"豆腐切块煎至微黄\",\"生菜和紫甘蓝铺底\",\"混合后即可食用\"]','可加少量柠檬汁提味。',NULL,NULL,0,4.7,0,0,0,'素食偏好、控脂降脂','控脂降脂',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (110,'里脊肉土豆配芹菜','中式家常组合，适合日常均衡饮食。','晚餐','中式',20,'简单',1,261.4,261.4,27.8,19.6,7.7,3.3,'[\"里脊肉切片腌制\",\"土豆切块煮熟\",\"芹菜切段快炒\",\"三种食材组合装盘\"]','控糖阶段可减少土豆比例。',NULL,NULL,0,4.5,0,0,0,'维持体重、家庭饮食','维持体重',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (111,'牛油果酸奶水果碗','清爽型早餐，适合孕妇营养和轻食需求。','早餐','轻食',8,'简单',1,213.8,213.8,6.1,24.5,11.6,6.1,'[\"将无糖酸奶倒入碗中\",\"牛油果切块\",\"加入蓝莓和猕猴桃\",\"混合后即可食用\"]','孕妇营养可搭配全麦主食一起吃。',NULL,NULL,0,4.8,0,0,0,'孕妇营养、维持体重','孕妇营养',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (112,'三文鱼藜麦温沙拉','兼顾蛋白质和优质脂肪，适合健康增重和塑形。','午餐','轻食',20,'中等',1,454.6,454.6,33.7,36.2,19.3,5.4,'[\"藜麦煮熟保温\",\"三文鱼煎熟切块\",\"生菜和芦笋焯水\",\"混合食材后趁温热食用\"]','可作为训练后恢复餐。',NULL,NULL,0,4.9,0,0,0,'增肌塑形、健康增重','增肌塑形',1,'2026-03-24 21:40:37','2026-03-24 21:40:37');
INSERT INTO `recipe` VALUES (113,'西红柿炒鸡蛋','家常经典菜。西红柿炒出汁与鸡蛋同炒，酸甜开胃，蛋白与番茄红素都不错。','晚餐','中式',15,'简单',2,262.6,131.3,17.2,7.8,18.1,2.2,'[\"西红柿洗净切块，鸡蛋打散加少许盐搅匀。\",\"热锅少油，倒入蛋液炒至半凝固盛出。\",\"下西红柿块中火炒 3 分钟至出汁，倒回鸡蛋翻匀，出锅前调盐即可。\"]','西红柿选熟透的更容易出汁；想少油可用不粘锅，把用油控制在 5g 以内。','',1,1,5,0,0,0,'均衡维持人群、控糖人群','维持',1,'2026-04-03 14:26:53','2026-11-02 17:32:52');
INSERT INTO `recipe` VALUES (600001,'全麦鸡蛋三明治','全麦面包、鸡蛋、生菜、番茄，共 4 种食材，约 248 kcal。','早餐','西式',8,'简单',1,248.1,248.1,15.6,29.3,7.6,5.2,'[\"全麦面包片放入烤箱 180℃ 烤 3 分钟至微脆。\",\"鸡蛋冷水下锅煮 8 分钟，捞出过凉水后切片。\",\"面包上依次铺生菜、番茄片、鸡蛋片，对折即可。\"]','全麦面包选配料表第一位是全麦粉的，纤维更高。',NULL,NULL,0,4.9,67,26,27,'减脂人群、控糖人群','减脂',0,'2025-11-01 08:00:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600002,'牛奶燕麦粥','燕麦、低脂牛奶、蓝莓，共 3 种食材，约 268 kcal。','早餐','中式',10,'简单',1,267.55,267.55,13.8,41.1,5.9,4.8,'[\"燕麦加牛奶小火煮 5 分钟，边煮边搅防粘底。\",\"粥体变稠后关火，静置 2 分钟。\",\"盛出撒上蓝莓即可。\"]','选即食燕麦可缩短到 2 分钟，但需注意是否额外加了糖。',NULL,NULL,0,4.5,67,167,13,'减脂人群、控糖人群','减脂',0,'2025-11-04 09:07:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600003,'小米南瓜粥','小米、南瓜，共 2 种食材，约 173 kcal。','早餐','中式',30,'较难',1,173,173,5.5,37.2,1.4,1.2,'[\"小米淘洗后浸泡 15 分钟。\",\"南瓜去皮切小块，与小米一同入锅，加水 600ml。\",\"大火烧开转小火煮 20 分钟，至南瓜软烂、粥稠即可。\"]','南瓜自带甜味，全程无需加糖。',NULL,NULL,0,4.2,76,41,18,'减脂人群、控脂人群','减脂',0,'2025-11-06 10:14:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600004,'豆浆紫薯燕麦糊','豆浆、紫薯、燕麦，共 3 种食材，约 241 kcal。','早餐','中式',12,'中等',1,240.8,240.8,13.2,37.1,5.7,6.4,'[\"紫薯蒸 15 分钟至软，去皮压成泥。\",\"豆浆小火加热，加入燕麦煮 3 分钟。\",\"倒入紫薯泥搅匀，再煮 2 分钟即可。\"]','紫薯的花青素怕高温久煮，出锅前再拌入能保留更多。',NULL,NULL,0,4.2,26,281,23,'减脂人群、控糖人群','减脂',0,'2025-11-07 11:21:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600005,'希腊酸奶蓝莓杯','希腊酸奶、蓝莓、核桃、燕麦，共 4 种食材，约 300 kcal。','早餐','轻食',5,'简单',1,299.8,299.8,17.4,26.4,14.8,3.8,'[\"杯中先铺一层希腊酸奶。\",\"撒入燕麦与一半蓝莓，再加一层酸奶。\",\"顶部放剩余蓝莓和掰碎的核桃仁。\"]','希腊酸奶蛋白密度高，选无糖款可省下约 8g 添加糖。',NULL,NULL,0,4.5,24,234,16,'均衡维持人群','减脂',0,'2025-11-09 12:28:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600006,'鸡蛋清蔬菜卷','鸡蛋清、全麦面包、生菜、黄瓜，共 4 种食材，约 163 kcal。','早餐','中式',10,'简单',1,163.25,163.25,15.4,21.3,1.8,3.7,'[\"鸡蛋清打散，平底锅无油小火摊成蛋皮。\",\"黄瓜切细条，生菜洗净沥干。\",\"面包上放蛋皮、生菜、黄瓜条卷起，切段即可。\"]','只用蛋清可把这份早餐的脂肪控制在 5g 以内。',NULL,NULL,0,4.3,30,270,6,'减脂人群、控脂人群','减脂',0,'2025-11-12 13:35:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600007,'玉米鸡蛋早餐盘','玉米、鸡蛋、西红柿、核桃，共 4 种食材，约 285 kcal。','早餐','中式',15,'中等',1,285.1,285.1,13.1,33,13.8,5.2,'[\"玉米切段上锅蒸 12 分钟。\",\"鸡蛋同步蒸 10 分钟。\",\"西红柿切块装盘，配核桃仁一同上桌。\"]','整根蒸玉米比玉米粒罐头纤维更完整。',NULL,NULL,0,4.7,34,271,7,'控糖人群','减脂',0,'2025-11-14 14:42:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600008,'荞麦面蔬菜汤','荞麦面、小白菜、鸡蛋，共 3 种食材，约 151 kcal。','早餐','中式',15,'中等',1,150.95,150.95,10.8,16.1,5.5,2.5,'[\"荞麦面下沸水煮 5 分钟，捞出过凉水。\",\"另起锅烧水，氽入小白菜 1 分钟。\",\"水中打入鸡蛋煮成蛋花，连汤浇在面上。\"]','荞麦面的 GI 低于普通面条，适合控糖人群。',NULL,NULL,0,4.3,35,312,10,'均衡维持人群','减脂',0,'2025-11-15 15:49:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600009,'无糖酸奶水果碗','无糖酸奶、香蕉、草莓、杏仁，共 4 种食材，约 224 kcal。','早餐','轻食',6,'简单',1,223.65,223.65,8.7,26.5,10.5,3.7,'[\"香蕉切片，草莓对半切。\",\"酸奶盛入碗中。\",\"铺上水果，撒杏仁片即可。\"]','无糖酸奶单吃不习惯时，用成熟的香蕉增甜比加蜂蜜更划算。',NULL,NULL,0,4.1,28,191,4,'均衡维持人群','减脂',0,'2025-11-17 16:56:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600010,'红薯豆浆早餐','红薯、豆浆、鸡蛋，共 3 种食材，约 263 kcal。','早餐','中式',25,'中等',1,263.35,263.35,16.1,30.3,9.3,5,'[\"红薯洗净不削皮，上锅蒸 20 分钟。\",\"豆浆加热至温热。\",\"鸡蛋煮 8 分钟，与红薯、豆浆一同装盘。\"]','红薯带皮蒸能减少水溶性纤维流失。',NULL,NULL,0,4.6,46,53,15,'控糖人群','减脂',0,'2025-11-20 17:03:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600011,'燕麦香蕉粥','燕麦、低脂牛奶、香蕉，共 3 种食材，约 307 kcal。','早餐','西式',10,'简单',1,306.8,306.8,14.4,50.9,6,5.9,'[\"燕麦与牛奶小火煮 5 分钟。\",\"香蕉切片，一半压成泥拌入粥中增稠。\",\"盛出后铺上剩余香蕉片。\"]','香蕉泥既增甜又增稠，可以省掉额外加的糖。',NULL,NULL,0,4.8,59,256,15,'减脂人群、控糖人群','减脂',0,'2025-11-22 18:10:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600012,'全麦面包牛油果','全麦面包、牛油果、鸡蛋、黑胡椒，共 4 种食材，约 314 kcal。','早餐','西式',6,'简单',1,313.9,313.9,15.3,31,15.4,8.8,'[\"全麦面包烤至微脆。\",\"牛油果挖出果肉压成泥，抹在面包上。\",\"放上水煮蛋切片，撒黑胡椒。\"]','牛油果热量密度高，半个（约 70g）是减脂期的合适份量。',NULL,NULL,0,4.8,14,124,10,'控糖人群','减脂',0,'2025-11-23 19:17:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600013,'豆腐蔬菜饼','豆腐、鸡蛋、胡萝卜，共 3 种食材，约 175 kcal。','早餐','中式',18,'中等',1,175.45,175.45,15.6,6,10.7,1.3,'[\"豆腐用勺子压碎，加入鸡蛋拌匀。\",\"胡萝卜擦丝拌入，加盐调味。\",\"平底锅少油，舀一勺面糊摊成小饼，两面各煎 2 分钟。\"]','豆腐本身含水量高，拌入鸡蛋即可成型，不必额外加面粉。',NULL,NULL,0,4.8,13,29,11,'均衡维持人群','减脂',0,'2025-11-25 08:24:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600014,'山药小米粥','山药、小米，共 2 种食材，约 196 kcal。','早餐','中式',30,'较难',1,195.7,195.7,6.1,41.2,1.4,1.5,'[\"小米淘洗，山药去皮切小丁。\",\"二者同入锅，加水 600ml 大火烧开。\",\"转小火煮 22 分钟至山药软糯。\"]','山药削皮时戴手套，避免黏液刺激皮肤发痒。',NULL,NULL,0,4.5,35,237,20,'减脂人群、控脂人群','减脂',0,'2025-11-28 09:31:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600015,'鸡蛋番茄全麦吐司','全麦面包、鸡蛋、西红柿、橄榄油，共 4 种食材，约 274 kcal。','早餐','西式',10,'简单',1,273.75,273.75,14.5,26.6,12.4,4.9,'[\"西红柿切丁，平底锅少油炒出汁。\",\"鸡蛋打散倒入，翻炒成蛋块。\",\"铺在烤过的吐司上即可。\"]','西红柿炒出汁再下蛋，蛋更嫩也更入味。',NULL,NULL,0,4.7,32,269,7,'控糖人群','减脂',0,'2025-11-30 10:38:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600016,'全麦鸡蛋三明治','全麦面包、鸡蛋、生菜、番茄，共 4 种食材，约 270 kcal。','早餐','西式',8,'简单',1,269.85,269.85,17,31.7,8.4,5.7,'[\"全麦面包片放入烤箱 180℃ 烤 3 分钟至微脆。\",\"鸡蛋冷水下锅煮 8 分钟，捞出过凉水后切片。\",\"面包上依次铺生菜、番茄片、鸡蛋片，对折即可。\"]','全麦面包选配料表第一位是全麦粉的，纤维更高。',NULL,NULL,0,4.8,24,91,10,'减脂人群、控糖人群','减脂',1,'2025-12-01 11:45:00','2026-11-02 17:32:20');
INSERT INTO `recipe` VALUES (600017,'牛奶燕麦粥','燕麦、低脂牛奶、蓝莓，共 3 种食材，约 299 kcal。','早餐','中式',10,'简单',1,299.05,299.05,15.4,46.1,6.6,5.5,'[\"燕麦加牛奶小火煮 5 分钟，边煮边搅防粘底。\",\"粥体变稠后关火，静置 2 分钟。\",\"盛出撒上蓝莓即可。\"]','选即食燕麦可缩短到 2 分钟，但需注意是否额外加了糖。',NULL,NULL,0,4.8,70,111,9,'减脂人群、控糖人群','减脂',1,'2025-12-03 12:52:00','2026-11-02 17:32:20');
INSERT INTO `recipe` VALUES (600018,'小米南瓜粥','小米、南瓜，共 2 种食材，约 194 kcal。','早餐','中式',30,'较难',1,193.65,193.65,6.2,41.6,1.5,1.3,'[\"小米淘洗后浸泡 15 分钟。\",\"南瓜去皮切小块，与小米一同入锅，加水 600ml。\",\"大火烧开转小火煮 20 分钟，至南瓜软烂、粥稠即可。\"]','南瓜自带甜味，全程无需加糖。',NULL,NULL,0,4.6,62,286,7,'减脂人群、控脂人群','减脂',0,'2025-12-06 13:59:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600019,'豆浆紫薯燕麦糊','豆浆、紫薯、燕麦，共 3 种食材，约 257 kcal。','早餐','中式',12,'中等',1,256.75,256.75,14.2,39.4,6.1,6.8,'[\"紫薯蒸 15 分钟至软，去皮压成泥。\",\"豆浆小火加热，加入燕麦煮 3 分钟。\",\"倒入紫薯泥搅匀，再煮 2 分钟即可。\"]','紫薯的花青素怕高温久煮，出锅前再拌入能保留更多。',NULL,NULL,0,4.5,46,217,22,'减脂人群、控糖人群','减脂',1,'2025-12-08 14:06:00','2026-11-02 17:32:20');
INSERT INTO `recipe` VALUES (600020,'希腊酸奶蓝莓杯','希腊酸奶、蓝莓、核桃、燕麦，共 4 种食材，约 317 kcal。','早餐','轻食',5,'简单',1,317.2,317.2,18.8,27.7,15.6,3.9,'[\"杯中先铺一层希腊酸奶。\",\"撒入燕麦与一半蓝莓，再加一层酸奶。\",\"顶部放剩余蓝莓和掰碎的核桃仁。\"]','希腊酸奶蛋白密度高，选无糖款可省下约 8g 添加糖。',NULL,NULL,0,4.4,42,46,21,'均衡维持人群','减脂',1,'2025-12-09 15:13:00','2026-11-02 17:32:20');
INSERT INTO `recipe` VALUES (600021,'鸡蛋清蔬菜卷','鸡蛋清、全麦面包、生菜、黄瓜，共 4 种食材，约 182 kcal。','早餐','中式',10,'简单',1,182.3,182.3,17.3,23.7,2,4.1,'[\"鸡蛋清打散，平底锅无油小火摊成蛋皮。\",\"黄瓜切细条，生菜洗净沥干。\",\"面包上放蛋皮、生菜、黄瓜条卷起，切段即可。\"]','只用蛋清可把这份早餐的脂肪控制在 5g 以内。',NULL,NULL,0,4.7,27,281,8,'减脂人群、控糖人群','减脂',1,'2025-12-11 16:20:00','2026-11-02 17:32:20');
INSERT INTO `recipe` VALUES (600022,'玉米鸡蛋早餐盘','玉米、鸡蛋、西红柿、核桃，共 4 种食材，约 309 kcal。','早餐','中式',15,'中等',1,309.05,309.05,14.3,36.6,14.6,5.7,'[\"玉米切段上锅蒸 12 分钟。\",\"鸡蛋同步蒸 10 分钟。\",\"西红柿切块装盘，配核桃仁一同上桌。\"]','整根蒸玉米比玉米粒罐头纤维更完整。',NULL,NULL,0,4.4,54,136,5,'控糖人群','减脂',1,'2025-12-14 17:27:00','2026-11-02 17:32:20');
INSERT INTO `recipe` VALUES (600023,'荞麦面蔬菜汤','荞麦面、小白菜、鸡蛋，共 3 种食材，约 165 kcal。','早餐','中式',15,'中等',1,164.95,164.95,11.9,17.5,6.1,2.7,'[\"荞麦面下沸水煮 5 分钟，捞出过凉水。\",\"另起锅烧水，氽入小白菜 1 分钟。\",\"水中打入鸡蛋煮成蛋花，连汤浇在面上。\"]','荞麦面的 GI 低于普通面条，适合控糖人群。',NULL,NULL,0,4.7,48,260,18,'均衡维持人群','减脂',1,'2025-12-15 18:34:00','2026-11-02 17:32:20');
