INSERT INTO `recipe` VALUES (600025,'红薯豆浆早餐','红薯、豆浆、鸡蛋，共 3 种食材，约 292 kcal。','早餐','中式',25,'中等',1,291.75,291.75,17.8,33.6,10.2,5.5,'[\"红薯洗净不削皮，上锅蒸 20 分钟。\",\"豆浆加热至温热。\",\"鸡蛋煮 8 分钟，与红薯、豆浆一同装盘。\"]','红薯带皮蒸能减少水溶性纤维流失。',NULL,NULL,0,4.6,64,35,14,'控糖人群','减脂',1,'2025-12-18 08:48:00','2026-11-02 17:32:20');
