INSERT INTO `recipe` VALUES (600038,'荞麦面蔬菜汤','荞麦面、小白菜、鸡蛋，共 3 种食材，约 179 kcal。','早餐','中式',15,'中等',1,178.95,178.95,12.9,18.9,6.6,2.9,'[\"荞麦面下沸水煮 5 分钟，捞出过凉水。\",\"另起锅烧水，氽入小白菜 1 分钟。\",\"水中打入鸡蛋煮成蛋花，连汤浇在面上。\"]','荞麦面的 GI 低于普通面条，适合控糖人群。',NULL,NULL,0,4.3,23,203,18,'均衡维持人群','减脂',0,'2026-01-13 09:19:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600039,'无糖酸奶水果碗','无糖酸奶、香蕉、草莓、杏仁，共 4 种食材，约 261 kcal。','早餐','轻食',6,'简单',1,260.55,260.55,10.3,31.4,11.8,4.2,'[\"香蕉切片，草莓对半切。\",\"酸奶盛入碗中。\",\"铺上水果，撒杏仁片即可。\"]','无糖酸奶单吃不习惯时，用成熟的香蕉增甜比加蜂蜜更划算。',NULL,NULL,0,4.3,47,210,5,'控糖人群','减脂',0,'2026-01-16 10:26:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600040,'红薯豆浆早餐','红薯、豆浆、鸡蛋，共 3 种食材，约 320 kcal。','早餐','中式',25,'中等',1,320.15,320.15,19.5,37,11.2,6,'[\"红薯洗净不削皮，上锅蒸 20 分钟。\",\"豆浆加热至温热。\",\"鸡蛋煮 8 分钟，与红薯、豆浆一同装盘。\"]','红薯带皮蒸能减少水溶性纤维流失。',NULL,NULL,0,4.7,63,288,17,'控糖人群','减脂',0,'2026-01-18 11:33:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600041,'燕麦香蕉粥','燕麦、低脂牛奶、香蕉，共 3 种食材，约 373 kcal。','早餐','西式',10,'简单',1,373,373,17.5,61.7,7.3,7.2,'[\"燕麦与牛奶小火煮 5 分钟。\",\"香蕉切片，一半压成泥拌入粥中增稠。\",\"盛出后铺上剩余香蕉片。\"]','香蕉泥既增甜又增稠，可以省掉额外加的糖。',NULL,NULL,0,4.2,36,28,18,'减脂人群、控糖人群','减脂',0,'2026-01-19 12:40:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600042,'全麦面包牛油果','全麦面包、牛油果、鸡蛋、黑胡椒，共 4 种食材，约 370 kcal。','早餐','西式',6,'简单',1,370.1,370.1,18.1,36.1,18.3,10.2,'[\"全麦面包烤至微脆。\",\"牛油果挖出果肉压成泥，抹在面包上。\",\"放上水煮蛋切片，撒黑胡椒。\"]','牛油果热量密度高，半个（约 70g）是减脂期的合适份量。',NULL,NULL,0,4.6,67,292,9,'控糖人群','减脂',0,'2026-01-21 13:47:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600043,'豆腐蔬菜饼','豆腐、鸡蛋、胡萝卜，共 3 种食材，约 210 kcal。','早餐','中式',18,'中等',1,210.25,210.25,18.6,7.5,12.7,1.7,'[\"豆腐用勺子压碎，加入鸡蛋拌匀。\",\"胡萝卜擦丝拌入，加盐调味。\",\"平底锅少油，舀一勺面糊摊成小饼，两面各煎 2 分钟。\"]','豆腐本身含水量高，拌入鸡蛋即可成型，不必额外加面粉。',NULL,NULL,0,4.4,40,35,11,'均衡维持人群','减脂',0,'2026-01-24 14:54:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600044,'山药小米粥','山药、小米，共 2 种食材，约 243 kcal。','早餐','中式',30,'较难',1,243.2,243.2,7.6,51.1,1.8,1.9,'[\"小米淘洗，山药去皮切小丁。\",\"二者同入锅，加水 600ml 大火烧开。\",\"转小火煮 22 分钟至山药软糯。\"]','山药削皮时戴手套，避免黏液刺激皮肤发痒。',NULL,NULL,0,4.5,37,304,13,'减脂人群、控脂人群','减脂',0,'2026-01-26 15:01:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600045,'鸡蛋番茄全麦吐司','全麦面包、鸡蛋、西红柿、橄榄油，共 4 种食材，约 318 kcal。','早餐','西式',10,'简单',1,317.55,317.55,17.2,31.6,13.8,5.9,'[\"西红柿切丁，平底锅少油炒出汁。\",\"鸡蛋打散倒入，翻炒成蛋块。\",\"铺在烤过的吐司上即可。\"]','西红柿炒出汁再下蛋，蛋更嫩也更入味。',NULL,NULL,0,4.4,65,149,4,'控糖人群','减脂',0,'2026-01-27 16:08:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600046,'全麦鸡蛋三明治','全麦面包、鸡蛋、生菜、番茄，共 4 种食材，约 325 kcal。','早餐','西式',8,'简单',1,324.95,324.95,20.4,38.5,10,6.9,'[\"全麦面包片放入烤箱 180℃ 烤 3 分钟至微脆。\",\"鸡蛋冷水下锅煮 8 分钟，捞出过凉水后切片。\",\"面包上依次铺生菜、番茄片、鸡蛋片，对折即可。\"]','全麦面包选配料表第一位是全麦粉的，纤维更高。',NULL,NULL,0,4.4,58,278,28,'减脂人群、增肌人群','减脂',0,'2026-01-29 17:15:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600047,'牛奶燕麦粥','燕麦、低脂牛奶、蓝莓，共 3 种食材，约 364 kcal。','早餐','中式',10,'简单',1,364.35,364.35,18.7,56.3,8,6.7,'[\"燕麦加牛奶小火煮 5 分钟，边煮边搅防粘底。\",\"粥体变稠后关火，静置 2 分钟。\",\"盛出撒上蓝莓即可。\"]','选即食燕麦可缩短到 2 分钟，但需注意是否额外加了糖。',NULL,NULL,0,4.8,65,267,25,'减脂人群、控糖人群','减脂',0,'2026-01-30 18:22:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600048,'小米南瓜粥','小米、南瓜，共 2 种食材，约 236 kcal。','早餐','中式',30,'较难',1,236.25,236.25,7.5,50.7,1.9,1.6,'[\"小米淘洗后浸泡 15 分钟。\",\"南瓜去皮切小块，与小米一同入锅，加水 600ml。\",\"大火烧开转小火煮 20 分钟，至南瓜软烂、粥稠即可。\"]','南瓜自带甜味，全程无需加糖。',NULL,NULL,0,4.7,60,105,8,'减脂人群、控脂人群','减脂',0,'2026-02-03 19:29:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600049,'鸡胸肉糙米饭','糙米、鸡胸肉、西兰花、橄榄油，共 4 种食材，约 334 kcal。','午餐','中式',25,'中等',1,334,334,38.4,22.4,10,3.6,'[\"糙米提前浸泡 30 分钟，蒸 30 分钟。\",\"鸡胸肉切片，黑胡椒腌 5 分钟，少油煎熟。\",\"西兰花氽水 1 分钟，与鸡肉一同铺在饭上。\"]','糙米比白米多浸泡一会儿才更容易蒸透。',NULL,NULL,0,4.4,32,266,10,'减脂人群、增肌人群','增肌',0,'2026-02-04 08:36:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600050,'牛肉藜麦碗','藜麦、瘦牛肉、彩椒、洋葱，共 4 种食材，约 443 kcal。','午餐','轻食',25,'中等',1,443.2,443.2,30.9,41.9,16.8,5.6,'[\"藜麦洗净，加水煮 15 分钟至透明圈出现。\",\"牛肉切条，少油大火快炒至变色。\",\"下彩椒、洋葱同炒 2 分钟，与藜麦拌匀。\"]','藜麦煮好后静置 5 分钟再翻松，口感更蓬松。',NULL,NULL,0,4.5,15,84,18,'增肌人群、控糖人群','减脂',0,'2026-02-06 09:43:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600051,'三文鱼藜麦沙拉','藜麦、三文鱼、生菜、紫甘蓝、橄榄油，共 5 种食材，约 437 kcal。','午餐','轻食',20,'中等',1,436.75,436.75,26.9,36.7,20.3,5,'[\"藜麦煮 15 分钟沥干放凉。\",\"三文鱼两面各煎 3 分钟至微焦。\",\"生菜、紫甘蓝撕块，与藜麦、三文鱼拌匀，淋橄榄油。\"]','三文鱼每周吃 2 次即可满足 Omega-3 需求。',NULL,NULL,0,4.2,10,306,8,'控糖人群','减脂',0,'2026-02-07 10:50:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600052,'鸡肉荞麦面','荞麦面、去皮鸡腿肉、小白菜、低钠酱油，共 4 种食材，约 231 kcal。','午餐','中式',20,'中等',1,231.05,231.05,23,16.9,8.2,2.6,'[\"荞麦面煮 5 分钟，过凉水沥干。\",\"鸡腿肉切块，少油煎至两面金黄。\",\"小白菜氽水，三者装碗，淋低钠酱油。\"]','鸡腿肉去皮后脂肪比带皮低约六成。',NULL,NULL,0,4.5,77,235,15,'增肌人群','增肌',0,'2026-02-11 11:57:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600053,'虾仁豆腐饭','米饭、虾仁、豆腐、西葫芦，共 4 种食材，约 326 kcal。','午餐','中式',22,'中等',1,326,326,33.2,38.6,5.2,1.5,'[\"虾仁去虾线，用料酒腌 5 分钟。\",\"豆腐切块，西葫芦切片。\",\"少油炒虾仁至变色，下豆腐西葫芦同炒 3 分钟，浇在米饭上。\"]','虾仁和豆腐都是低脂高蛋白，这道菜蛋白接近 30g。',NULL,NULL,0,4.7,73,169,14,'减脂人群、增肌人群','增肌',0,'2026-02-12 12:04:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600054,'牛肉土豆炖菜','土豆、牛肉、胡萝卜、洋葱，共 4 种食材，约 390 kcal。','午餐','中式',40,'较难',1,390.15,390.15,29.6,31.8,17.3,5.1,'[\"牛肉切块氽水去血沫。\",\"与土豆、胡萝卜、洋葱一同入锅，加水没过。\",\"大火烧开转小火炖 30 分钟，收汁即可。\"]','土豆当主食吃时，要相应减少米饭的分量。',NULL,NULL,0,4.4,11,218,7,'增肌人群、控糖人群','增肌',0,'2026-02-14 13:11:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600055,'鳕鱼玉米饭','糙米、鳕鱼、玉米、西兰花，共 4 种食材，约 243 kcal。','午餐','中式',25,'中等',1,243.05,243.05,25.9,31.4,2.4,4.5,'[\"糙米蒸 30 分钟。\",\"鳕鱼用厨房纸吸干水分，少油煎至两面金黄。\",\"玉米粒氽熟，与西兰花一同摆盘。\"]','鳕鱼刺少肉嫩，适合老人和孩子。',NULL,NULL,0,4.3,34,21,14,'减脂人群、增肌人群','增肌',0,'2026-02-15 14:18:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600056,'鹰嘴豆鸡胸沙拉','鹰嘴豆、鸡胸肉、黄瓜、番茄、橄榄油，共 5 种食材，约 363 kcal。','午餐','轻食',18,'中等',1,363.4,363.4,37.1,29.9,10.8,8,'[\"鹰嘴豆提前泡发后煮 20 分钟至软。\",\"鸡胸肉水煮 12 分钟，手撕成条。\",\"黄瓜番茄切块，全部拌匀，淋橄榄油与黑胡椒。\"]','鹰嘴豆纤维高，但也要计入主食量。',NULL,NULL,0,4.4,69,69,26,'减脂人群、增肌人群','增肌',0,'2026-02-19 15:25:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600057,'金枪鱼全麦意面','全麦面包、金枪鱼、番茄、洋葱，共 4 种食材，约 346 kcal。','午餐','西式',18,'中等',1,346.25,346.25,36.8,39.6,4.1,7.3,'[\"洋葱切丁，番茄切块。\",\"少油炒香洋葱，下番茄炒出汁。\",\"加入金枪鱼拌匀，配全麦面包食用。\"]','金枪鱼选水浸款，比油浸款少约 10g 脂肪。',NULL,NULL,0,4.4,53,319,15,'减脂人群、增肌人群','增肌',0,'2026-02-20 16:32:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600058,'巴沙鱼蔬菜饭','米饭、巴沙鱼、芦笋、彩椒，共 4 种食材，约 278 kcal。','午餐','中式',20,'中等',1,277.6,277.6,24.8,37.4,3.1,2.9,'[\"巴沙鱼切块，用黑胡椒略腌。\",\"少油煎鱼块至两面微黄。\",\"芦笋、彩椒氽水 1 分钟，与鱼一同铺在饭上。\"]','巴沙鱼价格便宜、脂肪低，是性价比很高的蛋白来源。',NULL,NULL,0,4.7,31,301,11,'减脂人群、增肌人群','增肌',0,'2026-02-22 17:39:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600059,'猪肉白菜炖粉条','瘦猪里脊、白菜、荞麦面，共 3 种食材，约 206 kcal。','午餐','中式',35,'较难',1,206.1,206.1,23,16.1,5.8,2.8,'[\"猪里脊切片，用淀粉抓匀。\",\"白菜切段，下锅炒软后加水烧开。\",\"下荞麦面与肉片，煮 8 分钟即可。\"]','用荞麦面代替传统粉条，GI 更低也更有饱腹感。',NULL,NULL,0,4.6,16,57,20,'减脂人群、增肌人群','增肌',0,'2026-02-23 18:46:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600060,'黑豆豆腐营养碗','黑豆、豆腐、糙米、菠菜，共 4 种食材，约 348 kcal。','午餐','轻食',22,'中等',1,348.3,348.3,24.1,51.6,6.8,11.4,'[\"黑豆提前泡一夜，煮 30 分钟。\",\"糙米蒸 25 分钟。\",\"豆腐切块少油煎，菠菜氽水，与黑豆糙米装碗。\"]','黑豆与豆腐搭配，植物蛋白的氨基酸组成更完整。',NULL,NULL,0,4.8,23,47,11,'减脂人群、增肌人群','减脂',0,'2026-02-26 19:53:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600061,'鸡胸肉紫薯便当','紫薯、鸡胸肉、西兰花、鸡蛋清，共 4 种食材，约 351 kcal。','午餐','中式',25,'中等',1,351.4,351.4,45,33.6,4.6,6.8,'[\"紫薯蒸 20 分钟。\",\"鸡胸肉水煮 12 分钟后撕条。\",\"西兰花氽水，蛋清煎成小饼，全部装盒。\"]','紫薯当主食比白米饭纤维高约 3 倍。',NULL,NULL,0,4.4,46,303,11,'减脂人群、增肌人群','增肌',0,'2026-02-28 08:00:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600062,'番茄牛肉意面','面条、牛肉、番茄、洋葱，共 4 种食材，约 354 kcal。','午餐','西式',25,'中等',1,354.35,354.35,27.3,27.8,16,2.5,'[\"面条煮 8 分钟，捞出备用。\",\"番茄洋葱切丁，少油炒软出汁。\",\"下牛肉末炒散，拌入面条即可。\"]','番茄的酸甜能减少用盐，控盐人群可以试试。',NULL,NULL,0,4.4,56,79,12,'增肌人群','增肌',0,'2026-03-01 09:07:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600063,'腐竹木耳鸡丝饭','米饭、腐竹、鸡胸肉、黄瓜，共 4 种食材，约 465 kcal。','午餐','中式',25,'中等',1,465.35,465.35,47.3,39.9,11.3,1.2,'[\"腐竹提前泡软，切段。\",\"鸡胸肉水煮后手撕，黄瓜切丝。\",\"少油炒腐竹 3 分钟，与鸡丝黄瓜拌饭。\"]','腐竹是浓缩的豆制品，热量密度高，按克数吃别贪多。',NULL,NULL,0,4.9,27,310,6,'增肌人群、控脂人群','增肌',0,'2026-03-03 10:14:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600064,'鸡胸肉糙米饭','糙米、鸡胸肉、西兰花、橄榄油，共 4 种食材，约 365 kcal。','午餐','中式',25,'中等',1,365,365,42.1,25.4,10.4,4,'[\"糙米提前浸泡 30 分钟，蒸 30 分钟。\",\"鸡胸肉切片，黑胡椒腌 5 分钟，少油煎熟。\",\"西兰花氽水 1 分钟，与鸡肉一同铺在饭上。\"]','糙米比白米多浸泡一会儿才更容易蒸透。',NULL,NULL,0,4.8,80,54,13,'减脂人群、增肌人群','增肌',1,'2026-03-06 11:21:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600065,'牛肉藜麦碗','藜麦、瘦牛肉、彩椒、洋葱，共 4 种食材，约 484 kcal。','午餐','轻食',25,'中等',1,484.2,484.2,33.7,45.8,18.3,6.1,'[\"藜麦洗净，加水煮 15 分钟至透明圈出现。\",\"牛肉切条，少油大火快炒至变色。\",\"下彩椒、洋葱同炒 2 分钟，与藜麦拌匀。\"]','藜麦煮好后静置 5 分钟再翻松，口感更蓬松。',NULL,NULL,0,4.7,55,287,21,'增肌人群、控糖人群','维持',0,'2026-03-08 12:28:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600066,'三文鱼藜麦沙拉','藜麦、三文鱼、生菜、紫甘蓝、橄榄油，共 5 种食材，约 479 kcal。','午餐','轻食',20,'中等',1,479,479,29.8,40.6,22,5.6,'[\"藜麦煮 15 分钟沥干放凉。\",\"三文鱼两面各煎 3 分钟至微焦。\",\"生菜、紫甘蓝撕块，与藜麦、三文鱼拌匀，淋橄榄油。\"]','三文鱼每周吃 2 次即可满足 Omega-3 需求。',NULL,NULL,0,4.9,12,298,11,'控糖人群','维持',1,'2026-03-09 13:35:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600067,'鸡肉荞麦面','荞麦面、去皮鸡腿肉、小白菜、低钠酱油，共 4 种食材，约 257 kcal。','午餐','中式',20,'中等',1,257.25,257.25,25.4,19.3,9,3,'[\"荞麦面煮 5 分钟，过凉水沥干。\",\"鸡腿肉切块，少油煎至两面金黄。\",\"小白菜氽水，三者装碗，淋低钠酱油。\"]','鸡腿肉去皮后脂肪比带皮低约六成。',NULL,NULL,0,4.5,38,36,11,'增肌人群','增肌',0,'2026-03-11 14:42:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600068,'虾仁豆腐饭','米饭、虾仁、豆腐、西葫芦，共 4 种食材，约 363 kcal。','午餐','中式',22,'中等',1,362.6,362.6,36.9,43,5.8,1.7,'[\"虾仁去虾线，用料酒腌 5 分钟。\",\"豆腐切块，西葫芦切片。\",\"少油炒虾仁至变色，下豆腐西葫芦同炒 3 分钟，浇在米饭上。\"]','虾仁和豆腐都是低脂高蛋白，这道菜蛋白接近 30g。',NULL,NULL,0,4.3,14,132,16,'减脂人群、增肌人群','增肌',1,'2026-03-14 15:49:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600069,'牛肉土豆炖菜','土豆、牛肉、胡萝卜、洋葱，共 4 种食材，约 431 kcal。','午餐','中式',40,'较难',1,430.7,430.7,32.6,35.3,19,5.7,'[\"牛肉切块氽水去血沫。\",\"与土豆、胡萝卜、洋葱一同入锅，加水没过。\",\"大火烧开转小火炖 30 分钟，收汁即可。\"]','土豆当主食吃时，要相应减少米饭的分量。',NULL,NULL,0,4.5,63,116,9,'增肌人群、控糖人群','增肌',0,'2026-03-16 16:56:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600070,'鳕鱼玉米饭','糙米、鳕鱼、玉米、西兰花，共 4 种食材，约 269 kcal。','午餐','中式',25,'中等',1,269.1,269.1,29.2,34.3,2.7,5,'[\"糙米蒸 30 分钟。\",\"鳕鱼用厨房纸吸干水分，少油煎至两面金黄。\",\"玉米粒氽熟，与西兰花一同摆盘。\"]','鳕鱼刺少肉嫩，适合老人和孩子。',NULL,NULL,0,4.4,73,168,5,'减脂人群、增肌人群','增肌',1,'2026-03-17 17:03:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600071,'鹰嘴豆鸡胸沙拉','鹰嘴豆、鸡胸肉、黄瓜、番茄、橄榄油，共 5 种食材，约 400 kcal。','午餐','轻食',18,'中等',1,399.6,399.6,41.3,33.4,11.4,9,'[\"鹰嘴豆提前泡发后煮 20 分钟至软。\",\"鸡胸肉水煮 12 分钟，手撕成条。\",\"黄瓜番茄切块，全部拌匀，淋橄榄油与黑胡椒。\"]','鹰嘴豆纤维高，但也要计入主食量。',NULL,NULL,0,4.1,35,282,8,'减脂人群、增肌人群','增肌',0,'2026-03-19 18:10:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600072,'金枪鱼全麦意面','全麦面包、金枪鱼、番茄、洋葱，共 4 种食材，约 388 kcal。','午餐','西式',18,'中等',1,387.9,387.9,41,44.5,4.6,8.2,'[\"洋葱切丁，番茄切块。\",\"少油炒香洋葱，下番茄炒出汁。\",\"加入金枪鱼拌匀，配全麦面包食用。\"]','金枪鱼选水浸款，比油浸款少约 10g 脂肪。',NULL,NULL,0,4.7,12,299,3,'减脂人群、增肌人群','增肌',0,'2026-03-20 19:17:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600073,'巴沙鱼蔬菜饭','米饭、巴沙鱼、芦笋、彩椒，共 4 种食材，约 312 kcal。','午餐','中式',20,'中等',1,312.2,312.2,28,42,3.5,3.3,'[\"巴沙鱼切块，用黑胡椒略腌。\",\"少油煎鱼块至两面微黄。\",\"芦笋、彩椒氽水 1 分钟，与鱼一同铺在饭上。\"]','巴沙鱼价格便宜、脂肪低，是性价比很高的蛋白来源。',NULL,NULL,0,4.8,78,110,19,'减脂人群、增肌人群','增肌',1,'2026-03-24 08:24:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600074,'猪肉白菜炖粉条','瘦猪里脊、白菜、荞麦面，共 3 种食材，约 228 kcal。','午餐','中式',35,'较难',1,227.9,227.9,25.6,17.6,6.4,3.1,'[\"猪里脊切片，用淀粉抓匀。\",\"白菜切段，下锅炒软后加水烧开。\",\"下荞麦面与肉片，煮 8 分钟即可。\"]','用荞麦面代替传统粉条，GI 更低也更有饱腹感。',NULL,NULL,0,4.8,57,74,23,'减脂人群、增肌人群','增肌',0,'2026-03-25 09:31:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600075,'黑豆豆腐营养碗','黑豆、豆腐、糙米、菠菜，共 4 种食材，约 381 kcal。','午餐','轻食',22,'中等',1,380.8,380.8,26.4,56.4,7.5,12.5,'[\"黑豆提前泡一夜，煮 30 分钟。\",\"糙米蒸 25 分钟。\",\"豆腐切块少油煎，菠菜氽水，与黑豆糙米装碗。\"]','黑豆与豆腐搭配，植物蛋白的氨基酸组成更完整。',NULL,NULL,0,4.4,19,138,6,'减脂人群、增肌人群','减脂',0,'2026-03-27 10:38:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600076,'鸡胸肉紫薯便当','紫薯、鸡胸肉、西兰花、鸡蛋清，共 4 种食材，约 386 kcal。','午餐','中式',25,'中等',1,386.2,386.2,49.1,37.3,5,7.5,'[\"紫薯蒸 20 分钟。\",\"鸡胸肉水煮 12 分钟后撕条。\",\"西兰花氽水，蛋清煎成小饼，全部装盒。\"]','紫薯当主食比白米饭纤维高约 3 倍。',NULL,NULL,0,4.5,56,256,17,'减脂人群、增肌人群','增肌',0,'2026-03-28 11:45:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600077,'番茄牛肉意面','面条、牛肉、番茄、洋葱，共 4 种食材，约 397 kcal。','午餐','西式',25,'中等',1,396.8,396.8,30.4,31.5,17.8,2.8,'[\"面条煮 8 分钟，捞出备用。\",\"番茄洋葱切丁，少油炒软出汁。\",\"下牛肉末炒散，拌入面条即可。\"]','番茄的酸甜能减少用盐，控盐人群可以试试。',NULL,NULL,0,4.3,42,128,16,'增肌人群','增肌',1,'2026-04-01 12:52:00','2026-11-02 17:32:21');
