INSERT INTO `recipe` VALUES (600088,'巴沙鱼蔬菜饭','米饭、巴沙鱼、芦笋、彩椒，共 4 种食材，约 347 kcal。','午餐','中式',20,'中等',1,346.8,346.8,31.2,46.5,3.9,3.7,'[\"巴沙鱼切块，用黑胡椒略腌。\",\"少油煎鱼块至两面微黄。\",\"芦笋、彩椒氽水 1 分钟，与鱼一同铺在饭上。\"]','巴沙鱼价格便宜、脂肪低，是性价比很高的蛋白来源。',NULL,NULL,0,4.5,23,248,11,'减脂人群、增肌人群','增肌',0,'2026-04-21 11:09:00','2026-11-02 18:04:49');
