INSERT INTO `recipe` VALUES (600090,'黑豆豆腐营养碗','黑豆、豆腐、糙米、菠菜，共 4 种食材，约 413 kcal。','午餐','轻食',22,'中等',1,413.3,413.3,28.7,61.2,8.1,13.6,'[\"黑豆提前泡一夜，煮 30 分钟。\",\"糙米蒸 25 分钟。\",\"豆腐切块少油煎，菠菜氽水，与黑豆糙米装碗。\"]','黑豆与豆腐搭配，植物蛋白的氨基酸组成更完整。',NULL,NULL,0,4.7,12,141,8,'减脂人群、增肌人群','减脂',0,'2026-04-26 13:23:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600091,'鸡胸肉紫薯便当','紫薯、鸡胸肉、西兰花、鸡蛋清，共 4 种食材，约 421 kcal。','午餐','中式',25,'中等',1,421,421,53.3,41,5.4,8.3,'[\"紫薯蒸 20 分钟。\",\"鸡胸肉水煮 12 分钟后撕条。\",\"西兰花氽水，蛋清煎成小饼，全部装盒。\"]','紫薯当主食比白米饭纤维高约 3 倍。',NULL,NULL,0,4.5,32,265,13,'减脂人群、增肌人群','增肌',1,'2026-04-28 14:30:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600092,'番茄牛肉意面','面条、牛肉、番茄、洋葱，共 4 种食材，约 439 kcal。','午餐','西式',25,'中等',1,439.25,439.25,33.5,35.3,19.6,3.1,'[\"面条煮 8 分钟，捞出备用。\",\"番茄洋葱切丁，少油炒软出汁。\",\"下牛肉末炒散，拌入面条即可。\"]','番茄的酸甜能减少用盐，控盐人群可以试试。',NULL,NULL,0,4.6,48,185,7,'增肌人群','增肌',0,'2026-04-29 15:37:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600093,'腐竹木耳鸡丝饭','米饭、腐竹、鸡胸肉、黄瓜，共 4 种食材，约 582 kcal。','午餐','中式',25,'中等',1,582.25,582.25,58.9,49.8,14.3,1.5,'[\"腐竹提前泡软，切段。\",\"鸡胸肉水煮后手撕，黄瓜切丝。\",\"少油炒腐竹 3 分钟，与鸡丝黄瓜拌饭。\"]','腐竹是浓缩的豆制品，热量密度高，按克数吃别贪多。',NULL,NULL,0,4.2,50,84,16,'增肌人群、控脂人群','增肌',0,'2026-05-01 16:44:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600094,'鸡胸肉糙米饭','糙米、鸡胸肉、西兰花、橄榄油，共 4 种食材，约 430 kcal。','午餐','中式',25,'中等',1,429.7,429.7,50.8,30.3,11.6,4.8,'[\"糙米提前浸泡 30 分钟，蒸 30 分钟。\",\"鸡胸肉切片，黑胡椒腌 5 分钟，少油煎熟。\",\"西兰花氽水 1 分钟，与鸡肉一同铺在饭上。\"]','糙米比白米多浸泡一会儿才更容易蒸透。',NULL,NULL,0,4.7,61,183,6,'减脂人群、增肌人群','增肌',0,'2026-05-04 17:51:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600095,'牛肉藜麦碗','藜麦、瘦牛肉、彩椒、洋葱，共 4 种食材，约 576 kcal。','午餐','轻食',25,'中等',1,575.75,575.75,40.4,53.8,21.9,7.2,'[\"藜麦洗净，加水煮 15 分钟至透明圈出现。\",\"牛肉切条，少油大火快炒至变色。\",\"下彩椒、洋葱同炒 2 分钟，与藜麦拌匀。\"]','藜麦煮好后静置 5 分钟再翻松，口感更蓬松。',NULL,NULL,0,4.5,20,71,22,'增肌人群、控糖人群','增肌',0,'2026-05-05 18:58:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600096,'三文鱼藜麦沙拉','藜麦、三文鱼、生菜、紫甘蓝、橄榄油，共 5 种食材，约 563 kcal。','午餐','轻食',20,'中等',1,562.75,562.75,35.7,48.2,25.3,6.6,'[\"藜麦煮 15 分钟沥干放凉。\",\"三文鱼两面各煎 3 分钟至微焦。\",\"生菜、紫甘蓝撕块，与藜麦、三文鱼拌匀，淋橄榄油。\"]','三文鱼每周吃 2 次即可满足 Omega-3 需求。',NULL,NULL,0,4.4,26,276,9,'增肌人群、控糖人群','维持',0,'2026-05-07 19:05:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600097,'鸡肉荞麦面','荞麦面、去皮鸡腿肉、小白菜、低钠酱油，共 4 种食材，约 304 kcal。','午餐','中式',20,'中等',1,304.05,304.05,30,22.9,10.7,3.5,'[\"荞麦面煮 5 分钟，过凉水沥干。\",\"鸡腿肉切块，少油煎至两面金黄。\",\"小白菜氽水，三者装碗，淋低钠酱油。\"]','鸡腿肉去皮后脂肪比带皮低约六成。',NULL,NULL,0,4.9,33,148,7,'增肌人群','增肌',0,'2026-05-08 08:12:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600098,'虾仁豆腐饭','米饭、虾仁、豆腐、西葫芦，共 4 种食材，约 435 kcal。','午餐','中式',22,'中等',1,434.95,434.95,44.2,51.5,6.9,2,'[\"虾仁去虾线，用料酒腌 5 分钟。\",\"豆腐切块，西葫芦切片。\",\"少油炒虾仁至变色，下豆腐西葫芦同炒 3 分钟，浇在米饭上。\"]','虾仁和豆腐都是低脂高蛋白，这道菜蛋白接近 30g。',NULL,NULL,0,4.2,80,308,10,'减脂人群、增肌人群','增肌',0,'2026-05-12 09:19:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600099,'牛肉土豆炖菜','土豆、牛肉、胡萝卜、洋葱，共 4 种食材，约 512 kcal。','午餐','中式',40,'较难',1,511.8,511.8,38.6,42.3,22.5,6.8,'[\"牛肉切块氽水去血沫。\",\"与土豆、胡萝卜、洋葱一同入锅，加水没过。\",\"大火烧开转小火炖 30 分钟，收汁即可。\"]','土豆当主食吃时，要相应减少米饭的分量。',NULL,NULL,0,4.2,79,62,7,'增肌人群、控糖人群','增肌',0,'2026-05-13 10:26:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600100,'鳕鱼玉米饭','糙米、鳕鱼、玉米、西兰花，共 4 种食材，约 321 kcal。','午餐','中式',25,'中等',1,320.95,320.95,34.8,40.9,3.2,5.9,'[\"糙米蒸 30 分钟。\",\"鳕鱼用厨房纸吸干水分，少油煎至两面金黄。\",\"玉米粒氽熟，与西兰花一同摆盘。\"]','鳕鱼刺少肉嫩，适合老人和孩子。',NULL,NULL,0,4.2,21,287,7,'减脂人群、增肌人群','增肌',0,'2026-05-15 11:33:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600101,'鹰嘴豆鸡胸沙拉','鹰嘴豆、鸡胸肉、黄瓜、番茄、橄榄油，共 5 种食材，约 470 kcal。','午餐','轻食',18,'中等',1,470.35,470.35,49.5,40,12.7,10.7,'[\"鹰嘴豆提前泡发后煮 20 分钟至软。\",\"鸡胸肉水煮 12 分钟，手撕成条。\",\"黄瓜番茄切块，全部拌匀，淋橄榄油与黑胡椒。\"]','鹰嘴豆纤维高，但也要计入主食量。',NULL,NULL,0,4.7,69,163,13,'增肌人群、控糖人群','增肌',0,'2026-05-16 12:40:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600102,'金枪鱼全麦意面','全麦面包、金枪鱼、番茄、洋葱，共 4 种食材，约 471 kcal。','午餐','西式',18,'中等',1,471.2,471.2,49.5,54.4,5.6,10,'[\"洋葱切丁，番茄切块。\",\"少油炒香洋葱，下番茄炒出汁。\",\"加入金枪鱼拌匀，配全麦面包食用。\"]','金枪鱼选水浸款，比油浸款少约 10g 脂肪。',NULL,NULL,0,4.5,17,162,12,'增肌人群、控糖人群','增肌',0,'2026-05-20 13:47:00','2026-11-02 18:04:49');
