INSERT INTO `recipe` VALUES (600107,'番茄牛肉意面','面条、牛肉、番茄、洋葱，共 4 种食材，约 476 kcal。','午餐','西式',25,'中等',1,475.75,475.75,36.5,37.8,21.4,3.4,'[\"面条煮 8 分钟，捞出备用。\",\"番茄洋葱切丁，少油炒软出汁。\",\"下牛肉末炒散，拌入面条即可。\"]','番茄的酸甜能减少用盐，控盐人群可以试试。',NULL,NULL,0,4.6,71,186,7,'增肌人群','增肌',0,'2026-05-29 18:22:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600108,'腐竹木耳鸡丝饭','米饭、腐竹、鸡胸肉、黄瓜，共 4 种食材，约 640 kcal。','午餐','中式',25,'中等',1,639.95,639.95,64.7,54.6,15.8,1.7,'[\"腐竹提前泡软，切段。\",\"鸡胸肉水煮后手撕，黄瓜切丝。\",\"少油炒腐竹 3 分钟，与鸡丝黄瓜拌饭。\"]','腐竹是浓缩的豆制品，热量密度高，按克数吃别贪多。',NULL,NULL,0,4.7,58,41,7,'增肌人群、控脂人群','增肌',0,'2026-05-31 19:29:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600109,'冬瓜虾仁汤配糙米饭','冬瓜、虾仁、豆腐、糙米，共 4 种食材，约 218 kcal。','晚餐','中式',20,'中等',1,218.2,218.2,29.2,17.7,4.4,2.1,'[\"冬瓜去皮切片，豆腐切块。\",\"锅中加水烧开，下冬瓜煮 6 分钟。\",\"下虾仁与豆腐再煮 3 分钟；糙米蒸熟后另装一碗同食。\"]','冬瓜水分足、热量极低，配一小碗糙米才是一顿完整的晚餐。',NULL,NULL,0,4.8,25,226,18,'减脂人群、增肌人群','增肌',0,'2026-06-01 08:36:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600110,'白灼西兰花鸡胸配红薯','西兰花、鸡胸肉、红薯、低钠酱油，共 4 种食材，约 308 kcal。','晚餐','中式',25,'中等',1,308.15,308.15,36.9,31.7,4.3,6.8,'[\"西兰花掰小朵，沸水氽 2 分钟。\",\"鸡胸肉整块水煮 12 分钟，切片。\",\"红薯蒸 20 分钟，与西兰花鸡胸一同装盘，淋低钠酱油。\"]','水煮鸡胸先关火焖 3 分钟，肉不会发柴。',NULL,NULL,0,4.4,52,208,19,'减脂人群、增肌人群','增肌',0,'2026-06-05 09:43:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600111,'番茄豆腐汤配全麦面包','番茄、豆腐、鸡蛋清、全麦面包，共 4 种食材，约 255 kcal。','晚餐','中式',15,'中等',1,254.8,254.8,21.5,28.2,7.3,5.5,'[\"番茄切块，少油炒出汁。\",\"加水烧开，下豆腐块煮 5 分钟。\",\"淋入蛋清搅成蛋花，配全麦面包食用。\"]','番茄炒出红油再加汤，汤色和味道都会更好。',NULL,NULL,0,4.9,16,39,7,'减脂人群、增肌人群','减脂',0,'2026-06-06 10:50:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600112,'清蒸鲈鱼芦笋配米饭','鱼肉、芦笋、米饭、低钠酱油、蒜末，共 5 种食材，约 300 kcal。','晚餐','中式',25,'中等',1,299.9,299.9,32.6,28.5,5.9,2.4,'[\"鱼身划几刀，铺姜片蒸 10 分钟。\",\"芦笋氽水 2 分钟摆盘。\",\"淋低钠酱油撒蒜末，米饭另装一碗。\"]','蒸鱼时间按每 500g 约 8 分钟计，过久肉质会老。',NULL,NULL,0,4.4,47,211,5,'减脂人群、增肌人群','增肌',0,'2026-06-08 11:57:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600113,'凉拌黄瓜豆腐丝配玉米','黄瓜、豆腐、玉米、橄榄油、蒜末，共 5 种食材，约 242 kcal。','晚餐','中式',15,'中等',1,241.9,241.9,13.2,27.5,11.7,3.5,'[\"黄瓜切丝，豆腐切条焯水 1 分钟。\",\"碗中放低钠酱油、蒜末、少许醋调汁。\",\"浇在黄瓜豆腐上拌匀，配煮玉米同食。\"]','豆腐先焯水 1 分钟能去豆腥味，凉拌更好吃。',NULL,NULL,0,4.3,29,30,16,'均衡维持人群','减脂',0,'2026-06-09 12:04:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600114,'蘑菇鸡胸汤配荞麦面','蘑菇、鸡胸肉、小白菜、荞麦面，共 4 种食材，约 231 kcal。','晚餐','中式',25,'中等',1,231.3,231.3,34.9,16,3.8,3.2,'[\"蘑菇切片，鸡胸肉切片用淀粉抓匀。\",\"锅中水烧开，下蘑菇煮 5 分钟，再下荞麦面煮 5 分钟。\",\"最后放鸡肉片与小白菜，煮 3 分钟即可。\"]','鸡肉切片后用淀粉抓一下，久煮也不柴。',NULL,NULL,0,4.3,15,169,7,'减脂人群、增肌人群','增肌',0,'2026-06-13 13:11:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600115,'菠菜豆腐煲','菠菜、豆腐、糙米、蒜末，共 4 种食材，约 202 kcal。','晚餐','中式',20,'中等',1,202.15,202.15,16.5,21.7,7.5,4.5,'[\"菠菜洗净切段，豆腐切块。\",\"少油爆香蒜末，加水烧开下豆腐煮 5 分钟。\",\"最后放菠菜烫 1 分钟，配糙米饭食用。\"]','菠菜草酸较高，氽水后再入锅更利于钙吸收。',NULL,NULL,0,4.6,67,143,10,'控糖人群','减脂',0,'2026-06-14 14:18:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600116,'白菜豆腐丸子汤配米饭','白菜、豆腐、鸡蛋清、胡萝卜、米饭，共 5 种食材，约 222 kcal。','晚餐','中式',30,'较难',1,221.9,221.9,16.6,30.2,4.9,2.9,'[\"豆腐压碎，与蛋清、胡萝卜末拌成馅。\",\"搓成小丸子，下入微沸的水中定型。\",\"加白菜叶煮 5 分钟，配米饭同食。\"]','丸子下锅时水保持微沸，大火容易冲散。',NULL,NULL,0,4.5,68,262,12,'减脂人群、控脂人群','减脂',0,'2026-06-16 15:25:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600117,'香煎鳕鱼配芦笋土豆','鳕鱼、芦笋、土豆、橄榄油、黑胡椒，共 5 种食材，约 262 kcal。','晚餐','西式',25,'中等',1,261.95,261.95,27,25.7,6.2,5.6,'[\"鳕鱼吸干水分，两面抹黑胡椒。\",\"土豆切块蒸 15 分钟。\",\"平底锅少油，中火每面煎鱼 3 分钟，芦笋同锅煎 2 分钟。\"]','鱼下锅前一定吸干水分，否则煎不出焦壳。',NULL,NULL,0,4.7,30,319,5,'减脂人群、增肌人群','增肌',0,'2026-06-17 16:32:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600118,'冬瓜海带虾仁汤配糙米','冬瓜、海带、虾仁、糙米，共 4 种食材，约 157 kcal。','晚餐','中式',25,'中等',1,156.75,156.75,16.2,22.2,1.3,2.8,'[\"海带提前泡发切丝，冬瓜切片。\",\"锅中水烧开，下海带煮 8 分钟。\",\"下冬瓜与虾仁再煮 5 分钟，配糙米饭同食。\"]','海带含碘丰富，甲状腺功能异常者需遵医嘱控制。',NULL,NULL,0,4.4,8,141,28,'减脂人群、控脂人群','减脂',0,'2026-06-19 17:39:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600119,'西葫芦炒蛋配全麦面包','西葫芦、鸡蛋、全麦面包、橄榄油，共 4 种食材，约 362 kcal。','晚餐','中式',15,'中等',1,362.25,362.25,22.1,28.6,18,5.5,'[\"西葫芦切片，鸡蛋打散。\",\"热锅少油，先炒蛋至半凝固盛出。\",\"下西葫芦炒软，倒回鸡蛋翻匀，配面包食用。\"]','西葫芦出水多，全程大火快炒口感更脆。',NULL,NULL,0,4.8,57,283,26,'控糖人群','减脂',0,'2026-06-22 18:46:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600120,'茄子青椒炒鸡丁配米饭','茄子、青椒、鸡胸肉、米饭、橄榄油，共 5 种食材，约 345 kcal。','晚餐','中式',25,'中等',1,344.85,344.85,32.4,34.4,8.9,3.2,'[\"茄子切丁，撒盐静置 10 分钟挤去水分。\",\"鸡胸肉切丁，少油炒至变色盛出。\",\"下茄丁青椒炒软，倒回鸡丁翻匀，配米饭。\"]','茄子预先挤水可大幅减少吸油量。',NULL,NULL,0,4.1,45,134,14,'减脂人群、增肌人群','增肌',0,'2026-06-24 19:53:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600121,'牛肉胡萝卜清汤配土豆','牛肉、胡萝卜、洋葱、土豆，共 4 种食材，约 413 kcal。','晚餐','中式',55,'较难',1,413.3,413.3,32,31.7,19.1,6.4,'[\"牛肉切块氽水，冲净浮沫。\",\"与洋葱同入锅，加水大火烧开转小火炖 40 分钟。\",\"下胡萝卜和土豆块再炖 15 分钟即可。\"]','氽水后用温水冲洗，冷水会让肉纤维骤然收缩变柴。',NULL,NULL,0,4.4,74,320,12,'增肌人群、控糖人群','增肌',0,'2026-06-25 08:00:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600122,'毛豆拌豆腐配紫薯','毛豆、豆腐、紫薯、橄榄油、蒜末，共 5 种食材，约 313 kcal。','晚餐','中式',25,'中等',1,312.75,312.75,20.3,30.7,14.1,7.4,'[\"毛豆煮 6 分钟去壳。\",\"豆腐切小块焯水 1 分钟。\",\"混合加蒜末与低钠酱油拌匀，紫薯蒸熟同食。\"]','毛豆的植物蛋白和纤维都不低，很适合晚餐。',NULL,NULL,0,4.4,39,42,26,'增肌人群、控糖人群','减脂',0,'2026-06-27 09:07:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600123,'清炒时蔬配鸡蛋清与米饭','小白菜、彩椒、鸡蛋清、米饭、橄榄油，共 5 种食材，约 218 kcal。','晚餐','中式',20,'中等',1,218.45,218.45,12.6,29.7,5.9,3.2,'[\"小白菜切段，彩椒切丝。\",\"蛋清炒至凝固盛出。\",\"下蔬菜大火快炒 2 分钟，倒回蛋清翻匀，配米饭。\"]','只用蛋清能把这道菜的脂肪控制在 5g 以内。',NULL,NULL,0,4.5,70,160,6,'减脂人群、控脂人群','减脂',0,'2026-06-30 10:14:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600124,'冬瓜虾仁汤配糙米饭','冬瓜、虾仁、豆腐、糙米，共 4 种食材，约 243 kcal。','晚餐','中式',20,'中等',1,242.9,242.9,32.6,19.4,5,2.4,'[\"冬瓜去皮切片，豆腐切块。\",\"锅中加水烧开，下冬瓜煮 6 分钟。\",\"下虾仁与豆腐再煮 3 分钟；糙米蒸熟后另装一碗同食。\"]','冬瓜水分足、热量极低，配一小碗糙米才是一顿完整的晚餐。',NULL,NULL,0,4.6,37,270,10,'减脂人群、增肌人群','增肌',1,'2026-07-02 11:21:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600125,'白灼西兰花鸡胸配红薯','西兰花、鸡胸肉、红薯、低钠酱油，共 4 种食材，约 338 kcal。','晚餐','中式',25,'中等',1,338.35,338.35,40.6,34.7,4.7,7.5,'[\"西兰花掰小朵，沸水氽 2 分钟。\",\"鸡胸肉整块水煮 12 分钟，切片。\",\"红薯蒸 20 分钟，与西兰花鸡胸一同装盘，淋低钠酱油。\"]','水煮鸡胸先关火焖 3 分钟，肉不会发柴。',NULL,NULL,0,4.7,29,297,8,'减脂人群、增肌人群','增肌',0,'2026-07-03 12:28:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600126,'番茄豆腐汤配全麦面包','番茄、豆腐、鸡蛋清、全麦面包，共 4 种食材，约 280 kcal。','晚餐','中式',15,'中等',1,280.05,280.05,23.6,31,8,6,'[\"番茄切块，少油炒出汁。\",\"加水烧开，下豆腐块煮 5 分钟。\",\"淋入蛋清搅成蛋花，配全麦面包食用。\"]','番茄炒出红油再加汤，汤色和味道都会更好。',NULL,NULL,0,4.6,10,133,4,'减脂人群、增肌人群','增肌',1,'2026-07-05 13:35:00','2026-11-02 17:32:21');
