INSERT INTO `recipe` VALUES (600137,'毛豆拌豆腐配紫薯','毛豆、豆腐、紫薯、橄榄油、蒜末，共 5 种食材，约 345 kcal。','晚餐','中式',25,'中等',1,345.45,345.45,23,34,15.4,8.3,'[\"毛豆煮 6 分钟去壳。\",\"豆腐切小块焯水 1 分钟。\",\"混合加蒜末与低钠酱油拌匀，紫薯蒸熟同食。\"]','毛豆的植物蛋白和纤维都不低，很适合晚餐。',NULL,NULL,0,4.2,39,98,28,'增肌人群、控糖人群','减脂',1,'2026-07-27 12:52:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600138,'清炒时蔬配鸡蛋清与米饭','小白菜、彩椒、鸡蛋清、米饭、橄榄油，共 5 种食材，约 240 kcal。','晚餐','中式',20,'中等',1,240.3,240.3,14.3,33.3,6,3.6,'[\"小白菜切段，彩椒切丝。\",\"蛋清炒至凝固盛出。\",\"下蔬菜大火快炒 2 分钟，倒回蛋清翻匀，配米饭。\"]','只用蛋清能把这道菜的脂肪控制在 5g 以内。',NULL,NULL,0,4.2,24,73,13,'减脂人群、控脂人群','减脂',1,'2026-07-28 13:59:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600139,'冬瓜虾仁汤配糙米饭','冬瓜、虾仁、豆腐、糙米，共 4 种食材，约 268 kcal。','晚餐','中式',20,'中等',1,267.6,267.6,36,21.2,5.6,2.6,'[\"冬瓜去皮切片，豆腐切块。\",\"锅中加水烧开，下冬瓜煮 6 分钟。\",\"下虾仁与豆腐再煮 3 分钟；糙米蒸熟后另装一碗同食。\"]','冬瓜水分足、热量极低，配一小碗糙米才是一顿完整的晚餐。',NULL,NULL,0,4.4,36,166,12,'减脂人群、增肌人群','增肌',0,'2026-07-30 14:06:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600140,'白灼西兰花鸡胸配红薯','西兰花、鸡胸肉、红薯、低钠酱油，共 4 种食材，约 369 kcal。','晚餐','中式',25,'中等',1,368.55,368.55,44.3,37.8,5.1,8.2,'[\"西兰花掰小朵，沸水氽 2 分钟。\",\"鸡胸肉整块水煮 12 分钟，切片。\",\"红薯蒸 20 分钟，与西兰花鸡胸一同装盘，淋低钠酱油。\"]','水煮鸡胸先关火焖 3 分钟，肉不会发柴。',NULL,NULL,0,4.5,36,176,18,'减脂人群、增肌人群','增肌',1,'2026-08-02 15:13:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600141,'番茄豆腐汤配全麦面包','番茄、豆腐、鸡蛋清、全麦面包，共 4 种食材，约 305 kcal。','晚餐','中式',15,'中等',1,305.3,305.3,25.7,33.9,8.7,6.6,'[\"番茄切块，少油炒出汁。\",\"加水烧开，下豆腐块煮 5 分钟。\",\"淋入蛋清搅成蛋花，配全麦面包食用。\"]','番茄炒出红油再加汤，汤色和味道都会更好。',NULL,NULL,0,4.9,37,215,12,'减脂人群、增肌人群','增肌',0,'2026-08-04 16:20:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600142,'清蒸鲈鱼芦笋配米饭','鱼肉、芦笋、米饭、低钠酱油、蒜末，共 5 种食材，约 364 kcal。','晚餐','中式',25,'中等',1,364.3,364.3,39.7,34.4,7.2,2.9,'[\"鱼身划几刀，铺姜片蒸 10 分钟。\",\"芦笋氽水 2 分钟摆盘。\",\"淋低钠酱油撒蒜末，米饭另装一碗。\"]','蒸鱼时间按每 500g 约 8 分钟计，过久肉质会老。',NULL,NULL,0,4.5,53,36,10,'减脂人群、增肌人群','增肌',1,'2026-08-05 17:27:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600143,'凉拌黄瓜豆腐丝配玉米','黄瓜、豆腐、玉米、橄榄油、蒜末，共 5 种食材，约 281 kcal。','晚餐','中式',15,'中等',1,280.8,280.8,15.7,33.2,13,4.3,'[\"黄瓜切丝，豆腐切条焯水 1 分钟。\",\"碗中放低钠酱油、蒜末、少许醋调汁。\",\"浇在黄瓜豆腐上拌匀，配煮玉米同食。\"]','豆腐先焯水 1 分钟能去豆腥味，凉拌更好吃。',NULL,NULL,0,4.5,11,243,8,'控糖人群','减脂',1,'2026-08-07 18:34:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600144,'蘑菇鸡胸汤配荞麦面','蘑菇、鸡胸肉、小白菜、荞麦面，共 4 种食材，约 281 kcal。','晚餐','中式',25,'中等',1,281.2,281.2,42.5,19.3,4.6,3.8,'[\"蘑菇切片，鸡胸肉切片用淀粉抓匀。\",\"锅中水烧开，下蘑菇煮 5 分钟，再下荞麦面煮 5 分钟。\",\"最后放鸡肉片与小白菜，煮 3 分钟即可。\"]','鸡肉切片后用淀粉抓一下，久煮也不柴。',NULL,NULL,0,4.9,76,310,5,'减脂人群、增肌人群','增肌',1,'2026-08-10 19:41:00','2026-11-02 17:32:21');
INSERT INTO `recipe` VALUES (600145,'菠菜豆腐煲','菠菜、豆腐、糙米、蒜末，共 4 种食材，约 243 kcal。','晚餐','中式',20,'中等',1,242.95,242.95,20,25.7,9.2,5.4,'[\"菠菜洗净切段，豆腐切块。\",\"少油爆香蒜末，加水烧开下豆腐煮 5 分钟。\",\"最后放菠菜烫 1 分钟，配糙米饭食用。\"]','菠菜草酸较高，氽水后再入锅更利于钙吸收。',NULL,NULL,0,4.4,48,293,23,'增肌人群、控糖人群','减脂',0,'2026-08-12 08:48:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600146,'白菜豆腐丸子汤配米饭','白菜、豆腐、鸡蛋清、胡萝卜、米饭，共 5 种食材，约 275 kcal。','晚餐','中式',30,'较难',1,274.7,274.7,20.3,37.7,5.9,3.6,'[\"豆腐压碎，与蛋清、胡萝卜末拌成馅。\",\"搓成小丸子，下入微沸的水中定型。\",\"加白菜叶煮 5 分钟，配米饭同食。\"]','丸子下锅时水保持微沸，大火容易冲散。',NULL,NULL,0,4.9,78,310,20,'减脂人群、增肌人群','减脂',0,'2026-08-13 09:55:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600147,'香煎鳕鱼配芦笋土豆','鳕鱼、芦笋、土豆、橄榄油、黑胡椒，共 5 种食材，约 306 kcal。','晚餐','西式',25,'中等',1,305.95,305.95,33.1,29.9,6.5,6.4,'[\"鳕鱼吸干水分，两面抹黑胡椒。\",\"土豆切块蒸 15 分钟。\",\"平底锅少油，中火每面煎鱼 3 分钟，芦笋同锅煎 2 分钟。\"]','鱼下锅前一定吸干水分，否则煎不出焦壳。',NULL,NULL,0,4.2,77,21,18,'减脂人群、增肌人群','增肌',0,'2026-08-15 10:02:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600148,'冬瓜海带虾仁汤配糙米','冬瓜、海带、虾仁、糙米，共 4 种食材，约 186 kcal。','晚餐','中式',25,'中等',1,186.45,186.45,19.1,26.5,1.6,3.4,'[\"海带提前泡发切丝，冬瓜切片。\",\"锅中水烧开，下海带煮 8 分钟。\",\"下冬瓜与虾仁再煮 5 分钟，配糙米饭同食。\"]','海带含碘丰富，甲状腺功能异常者需遵医嘱控制。',NULL,NULL,0,4.5,41,65,8,'减脂人群、控脂人群','减脂',0,'2026-08-18 11:09:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600149,'西葫芦炒蛋配全麦面包','西葫芦、鸡蛋、全麦面包、橄榄油，共 4 种食材，约 425 kcal。','晚餐','中式',15,'中等',1,424.75,424.75,26.5,34.2,20.5,6.6,'[\"西葫芦切片，鸡蛋打散。\",\"热锅少油，先炒蛋至半凝固盛出。\",\"下西葫芦炒软，倒回鸡蛋翻匀，配面包食用。\"]','西葫芦出水多，全程大火快炒口感更脆。',NULL,NULL,0,4.9,35,267,23,'控糖人群','减脂',0,'2026-08-20 12:16:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600150,'茄子青椒炒鸡丁配米饭','茄子、青椒、鸡胸肉、米饭、橄榄油，共 5 种食材，约 413 kcal。','晚餐','中式',25,'中等',1,412.55,412.55,39.6,42.2,9.8,4,'[\"茄子切丁，撒盐静置 10 分钟挤去水分。\",\"鸡胸肉切丁，少油炒至变色盛出。\",\"下茄丁青椒炒软，倒回鸡丁翻匀，配米饭。\"]','茄子预先挤水可大幅减少吸油量。',NULL,NULL,0,4.2,53,152,12,'减脂人群、增肌人群','增肌',0,'2026-08-21 13:23:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600151,'牛肉胡萝卜清汤配土豆','牛肉、胡萝卜、洋葱、土豆，共 4 种食材，约 495 kcal。','晚餐','中式',55,'较难',1,494.9,494.9,38,38.9,22.6,7.8,'[\"牛肉切块氽水，冲净浮沫。\",\"与洋葱同入锅，加水大火烧开转小火炖 40 分钟。\",\"下胡萝卜和土豆块再炖 15 分钟即可。\"]','氽水后用温水冲洗，冷水会让肉纤维骤然收缩变柴。',NULL,NULL,0,4.7,60,39,12,'增肌人群、控糖人群','增肌',0,'2026-08-23 14:30:00','2026-11-02 18:04:49');
