INSERT INTO `recipe` VALUES (600161,'白菜豆腐丸子汤配米饭','白菜、豆腐、鸡蛋清、胡萝卜、米饭，共 5 种食材，约 301 kcal。','晚餐','中式',30,'较难',1,301.1,301.1,22.2,41.4,6.5,4,'[\"豆腐压碎，与蛋清、胡萝卜末拌成馅。\",\"搓成小丸子，下入微沸的水中定型。\",\"加白菜叶煮 5 分钟，配米饭同食。\"]','丸子下锅时水保持微沸，大火容易冲散。',NULL,NULL,0,4.1,25,180,9,'减脂人群、增肌人群','增肌',0,'2026-09-13 12:40:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600162,'香煎鳕鱼配芦笋土豆','鳕鱼、芦笋、土豆、橄榄油、黑胡椒，共 5 种食材，约 332 kcal。','晚餐','西式',25,'中等',1,331.8,331.8,36.3,32.9,6.6,7,'[\"鳕鱼吸干水分，两面抹黑胡椒。\",\"土豆切块蒸 15 分钟。\",\"平底锅少油，中火每面煎鱼 3 分钟，芦笋同锅煎 2 分钟。\"]','鱼下锅前一定吸干水分，否则煎不出焦壳。',NULL,NULL,0,4.7,34,51,4,'减脂人群、增肌人群','增肌',0,'2026-09-14 13:47:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600163,'冬瓜海带虾仁汤配糙米','冬瓜、海带、虾仁、糙米，共 4 种食材，约 201 kcal。','晚餐','中式',25,'中等',1,200.75,200.75,20.6,28.6,1.7,3.7,'[\"海带提前泡发切丝，冬瓜切片。\",\"锅中水烧开，下海带煮 8 分钟。\",\"下冬瓜与虾仁再煮 5 分钟，配糙米饭同食。\"]','海带含碘丰富，甲状腺功能异常者需遵医嘱控制。',NULL,NULL,0,4.4,72,129,25,'减脂人群、增肌人群','减脂',0,'2026-09-16 14:54:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600164,'西葫芦炒蛋配全麦面包','西葫芦、鸡蛋、全麦面包、橄榄油，共 4 种食材，约 455 kcal。','晚餐','中式',15,'中等',1,455.15,455.15,28.6,36.8,21.8,7,'[\"西葫芦切片，鸡蛋打散。\",\"热锅少油，先炒蛋至半凝固盛出。\",\"下西葫芦炒软，倒回鸡蛋翻匀，配面包食用。\"]','西葫芦出水多，全程大火快炒口感更脆。',NULL,NULL,0,4.6,51,310,26,'增肌人群、控糖人群','维持',0,'2026-09-17 15:01:00','2026-11-02 18:04:49');
INSERT INTO `recipe` VALUES (600165,'茄子青椒炒鸡丁配米饭','茄子、青椒、鸡胸肉、米饭、橄榄油，共 5 种食材，约 445 kcal。','晚餐','中式',25,'中等',1,445.4,445.4,43.2,45.9,10.2,4.3,'[\"茄子切丁，撒盐静置 10 分钟挤去水分。\",\"鸡胸肉切丁，少油炒至变色盛出。\",\"下茄丁青椒炒软，倒回鸡丁翻匀，配米饭。\"]','茄子预先挤水可大幅减少吸油量。',NULL,NULL,0,4.6,24,267,10,'减脂人群、增肌人群','增肌',0,'2026-09-20 16:08:00','2026-11-02 18:04:49');
