INSERT INTO `recipe` VALUES (700000,'南瓜小米糊','小米、南瓜，共 2 种食材，约 183 kcal。','早餐','中式',25,'中等',1,183.4,183.4,5.9,39.8,1.4,1.4,'[\"小米淘洗后浸泡 10 分钟。\",\"南瓜去皮切小块，与小米一同入锅加水 500ml。\",\"大火烧开转小火煮 18 分钟，用勺子压成糊即可。\"]','南瓜压成泥后再煮 2 分钟，口感更顺滑。',NULL,NULL,0,5,0,0,0,'减脂人群、控脂人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700001,'菠菜鸡蛋饼','鸡蛋、菠菜、橄榄油，共 3 种食材，约 229 kcal。','早餐','中式',12,'简单',1,228.86,228.86,17.2,4.8,16.1,2.2,'[\"菠菜焯水 30 秒后挤干切碎。\",\"鸡蛋打散，拌入菠菜碎。\",\"平底锅少油，倒入蛋液摊平，小火两面各煎 2 分钟。\"]','菠菜先焯水能去掉大部分草酸，口感也更嫩。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700002,'酸奶果仁燕麦杯','无糖酸奶、燕麦、开心果、草莓，共 4 种食材，约 299 kcal。','早餐','轻食',6,'简单',1,299.34,299.34,13.5,34.4,12.8,5.3,'[\"燕麦用干锅小火焙香 2 分钟。\",\"杯中铺一层酸奶，再铺燕麦。\",\"重复一层，顶部放开心果和草莓丁。\"]','燕麦焙过之后香气更明显，也更耐泡。',NULL,NULL,0,5,0,0,0,'控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700003,'番茄鸡蛋面','面条、鸡蛋、番茄、橄榄油，共 4 种食材，约 329 kcal。','早餐','中式',15,'中等',1,328.76,328.76,18.2,27.3,16.5,2.4,'[\"番茄切块，鸡蛋打散炒至凝固盛出。\",\"下番茄块炒出汁，加水 400ml 烧开。\",\"放入面条煮 5 分钟，倒回鸡蛋调味即可。\"]','番茄炒出汁再加水，汤底更浓郁。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700004,'紫薯山药泥','紫薯、山药、低脂牛奶，共 3 种食材，约 201 kcal。','早餐','中式',20,'中等',1,201.4,201.4,7.3,41.1,1.8,5,'[\"紫薯与山药去皮切块，上锅蒸 15 分钟。\",\"趁热压成泥，分次加入牛奶调至顺滑。\",\"装入碗中，可撒少许坚果碎。\"]','牛奶要分次少量加，一次倒多了会太稀。',NULL,NULL,0,5,0,0,0,'减脂人群、控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
