INSERT INTO `recipe` VALUES (700009,'鸡蛋敷山药粥','山药、小米、鸡蛋，共 3 种食材，约 280 kcal。','早餐','中式',30,'较难',1,280,280,13.3,41.7,7.2,1.8,'[\"小米淘洗，山药去皮切丁。\",\"加水 550ml 大火烧开，转小火煮 20 分钟。\",\"打入鸡蛋搅散成蛋花，再煮 2 分钟。\"]','蛋花要等粥煮好后再淋，久煮会老。',NULL,NULL,0,5,0,0,0,'减脂人群、控脂人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700010,'鲜果酸奶碗','希腊酸奶、猕猴桃、火龙果、腰果，共 4 种食材，约 269 kcal。','早餐','轻食',5,'简单',1,268.5,268.5,16,27.7,11.8,3.4,'[\"猕猴桃、火龙果切块。\",\"酸奶盛入碗中摊平。\",\"码上水果块，撒腰果。\"]','希腊酸奶蛋白高、碳水低，适合当减脂期早餐。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700011,'全麦三明治配豆浆','全麦面包、鸡蛋清、生菜、豆浆，共 4 种食材，约 275 kcal。','早餐','西式',8,'简单',1,274.85,274.85,24.9,30.7,6.2,5.8,'[\"蛋清煎成薄饼。\",\"全麦面包上铺生菜和蛋饼。\",\"对折后配豆浆食用。\"]','用蛋清代替全蛋，这份早餐脂肪能控制在 6g 以内。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700012,'小米红枣燕麦粥','燕麦、小米、红薯，共 3 种食材，约 293 kcal。','早餐','中式',25,'中等',1,292.95,292.95,9.5,58.6,3,6.4,'[\"小米淘洗，红薯切块。\",\"与燕麦一同入锅，加水 550ml。\",\"大火烧开转小火煮 20 分钟。\"]','红薯自带甜味，不需要额外加糖。',NULL,NULL,0,5,0,0,0,'减脂人群、控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700013,'蘑菇芝士烤蛋','蘑菇、鸡蛋、奶酪、橄榄油，共 4 种食材，约 268 kcal。','早餐','西式',18,'中等',1,268.22,268.22,21.2,5,18.4,1,'[\"蘑菇切片，少油炒软盛入烤碗。\",\"鸡蛋打散倒入碗中。\",\"铺上奶酪，烤箱 190℃ 烤 12 分钟。\"]','蘑菇先炒过再烤，能去掉多余水分。',NULL,NULL,0,5,0,0,0,'增肌人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700014,'燕麦豆浆杯','豆浆、燕麦、香蕉，共 3 种食材，约 278 kcal。','早餐','轻食',8,'简单',1,277.6,277.6,15.6,40.8,7.2,6.3,'[\"豆浆加热至微沸。\",\"冲入燕麦中闷 3 分钟。\",\"放入香蕉片即可。\"]','豆浆冲燕麦比牛奶更清爽，适合乳糖不耐。',NULL,NULL,0,5,0,0,0,'减脂人群、控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700015,'韭菜鸡蛋馒头片','馒头、鸡蛋、小白菜、橄榄油，共 4 种食材，约 372 kcal。','早餐','中式',12,'简单',1,372.36,372.36,20.4,36,16.6,1.7,'[\"馒头切片，鸡蛋打散。\",\"馒头片裹蛋液，平底锅少油煎至两面金黄。\",\"小白菜焯水后一同装盘。\"]','馒头片用隔夜的更好，太软会吸太多油。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700016,'紫甘蓝水果沙拉','紫甘蓝、苹果、葡萄、无糖酸奶，共 4 种食材，约 155 kcal。','早餐','轻食',8,'简单',1,155.4,155.4,3.9,33.3,2.4,4.7,'[\"紫甘蓝切细丝，苹果切块，葡萄对半切。\",\"装盘后淋上酸奶。\",\"拌匀即可食用。\"]','紫甘蓝切得越细口感越脆，也更好入味。',NULL,NULL,0,5,0,0,0,'减脂人群、控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700017,'蛋黄豆腐羹','豆腐、鸭蛋、小白菜，共 3 种食材，约 222 kcal。','早餐','中式',15,'中等',1,222.2,222.2,19.9,6,15.2,1,'[\"豆腐切小块，小白菜切碎。\",\"锅中加水烧开，下豆腐煮 3 分钟。\",\"淋入鸭蛋蛋液搅成蛋花，加白菜碎再煮 1 分钟。\"]','鸭蛋比鸡蛋香，做羹汤风味更足。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700018,'香菇滑鸡米饭','米饭、去皮鸡腿肉、蘑菇、胡萝卜、低钠酱油，共 5 种食材，约 376 kcal。','午餐','中式',25,'中等',1,376.48,376.48,29,41.7,10.4,2.9,'[\"鸡腿肉切块用淀粉抓匀，蘑菇切片。\",\"少油炒香鸡块至变色，下蘑菇胡萝卜同炒。\",\"加水焖 5 分钟收汁，淋酱油浇在米饭上。\"]','鸡腿肉用淀粉抓过更滑嫩，久煮也不柴。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700019,'番茄牛肉面','面条、瘦牛肉、番茄、洋葱，共 4 种食材，约 369 kcal。','午餐','中式',30,'较难',1,369.15,369.15,27.1,34.1,14.1,3.2,'[\"牛肉切薄片，番茄切块，洋葱切丝。\",\"少油炒香洋葱，下番茄炒出汁。\",\"加水烧开下面条煮 5 分钟，最后放牛肉片烫熟。\"]','牛肉片最后放，烫 30 秒即可，久煮会老。',NULL,NULL,0,5,0,0,0,'增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700020,'清蒸鱼配糙米饭','糙米、鱼肉、芦笋、低钠酱油，共 4 种食材，约 282 kcal。','午餐','中式',25,'中等',1,281.58,281.58,32.9,21.8,6.5,3.1,'[\"糙米提前泡 30 分钟，蒸 30 分钟。\",\"鱼身铺姜片蒸 10 分钟。\",\"芦笋焯水摆盘，淋酱油即可。\"]','蒸鱼时间按每 500g 约 8 分钟计。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700021,'青椒土豆丝炒肉','土豆、青椒、瘦猪里脊、米饭、橄榄油，共 5 种食材，约 433 kcal。','午餐','中式',20,'中等',1,432.7,432.7,26.5,54.6,11.8,4.9,'[\"土豆切细丝泡水去淀粉。\",\"肉丝炒至变色盛出。\",\"下土豆丝青椒大火快炒 3 分钟，倒回肉丝调味，配米饭。\"]','土豆丝泡冷水能去掉表面淀粉，炒出来更脆。',NULL,NULL,0,5,0,0,0,'减脂人群、控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700022,'虾仁玉米炒饭','米饭、虾仁、玉米、胡萝卜、鸡蛋，共 5 种食材，约 422 kcal。','午餐','中式',20,'中等',1,422.35,422.35,35,55.6,7.5,3.3,'[\"虾仁用料酒腌 5 分钟。\",\"鸡蛋炒散盛出。\",\"炒虾仁至变色，下米饭玉米胡萝卜丁翻炒，最后拌入鸡蛋。\"]','用隔夜饭炒更松散，不容易粘成团。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700023,'鳕鱼豆腐煲','鳕鱼、豆腐、番茄、米饭，共 4 种食材，约 343 kcal。','午餐','中式',25,'中等',1,343.4,343.4,36.5,34.3,7.2,2,'[\"鳕鱼切块，豆腐切块。\",\"番茄切块炒出汁，加水烧开。\",\"下豆腐煮 5 分钟，放鳕鱼块再煮 4 分钟，配米饭。\"]','鳕鱼肉质细嫩，最后下锅避免煮散。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700024,'藜麦鸡胸沙拉','藜麦、鸡胸肉、黄瓜、番茄、橄榄油，共 5 种食材，约 446 kcal。','午餐','轻食',20,'中等',1,445.66,445.66,43.2,41.3,11.6,5.2,'[\"藜麦煮 15 分钟沥干放凉。\",\"鸡胸肉水煮 12 分钟后撕成条。\",\"黄瓜番茄切块，全部拌匀淋橄榄油。\"]','藜麦煮好后再静置 5 分钟，口感更蓬松。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700025,'牛肉西兰花饭','米饭、牛里脊、西兰花、胡萝卜、低钠酱油，共 5 种食材，约 345 kcal。','午餐','中式',22,'中等',1,345.28,345.28,29.5,45.1,5.5,4.5,'[\"牛里脊切片用淀粉抓匀。\",\"西兰花胡萝卜焯水 2 分钟。\",\"少油快炒牛肉至变色，与蔬菜一起浇在饭上。\"]','牛肉逆纹切片，口感会嫩很多。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700026,'鹰嘴豆南瓜饭','鹰嘴豆、南瓜、糙米、菠菜，共 4 种食材，约 278 kcal。','午餐','轻食',28,'较难',1,278.1,278.1,13.1,52.7,3.4,10.2,'[\"鹰嘴豆提前泡发后煮 20 分钟。\",\"南瓜切块蒸 15 分钟，糙米蒸 25 分钟。\",\"菠菜焯水，全部混合装碗。\"]','鹰嘴豆纤维高，当主食吃要注意减米饭量。',NULL,NULL,0,5,0,0,0,'减脂人群、控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700027,'鸡肉蘑菇荞麦面','荞麦面、去皮鸡腿肉、蘑菇、小白菜，共 4 种食材，约 260 kcal。','午餐','中式',22,'中等',1,260.3,260.3,26.2,22.1,8.5,3.9,'[\"荞麦面煮 5 分钟过凉水。\",\"鸡腿肉切块煎至金黄。\",\"下蘑菇炒软，加面与小白菜翻匀即可。\"]','荞麦面 GI 低，适合控糖人群。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700028,'猪肉白菜炖豆腐','瘦猪里脊、白菜、豆腐、米饭，共 4 种食材，约 372 kcal。','午餐','中式',35,'较难',1,372.1,372.1,33.4,34.9,11.5,2.2,'[\"猪肉切片，白菜切段，豆腐切块。\",\"少油炒香肉片，下白菜炒软。\",\"加水烧开下豆腐炖 15 分钟，配米饭。\"]','白菜炖到软烂才够入味，别急着出锅。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700029,'金枪鱼土豆沙拉','土豆、金枪鱼、黄瓜、无糖酸奶、橄榄油，共 5 种食材，约 339 kcal。','午餐','西式',20,'中等',1,338.62,338.62,33.9,35.8,6.2,4.3,'[\"土豆切块蒸 15 分钟。\",\"黄瓜切丁，金枪鱼沥干。\",\"酸奶与橄榄油调成酱汁，全部拌匀。\"]','用酸奶代替沙拉酱，这份沙拉脂肪能少一半。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700030,'香菇鸡胸糙米饭','糙米、鸡胸肉、蘑菇、彩椒、低钠酱油，共 5 种食材，约 306 kcal。','午餐','中式',28,'较难',1,306.33,306.33,39.9,24.1,5.1,3.5,'[\"糙米泡 30 分钟后蒸 30 分钟。\",\"鸡胸切片，蘑菇切片。\",\"少油炒鸡胸至变色，下蘑菇彩椒炒 3 分钟，浇在饭上。\"]','鸡胸切片比整块煮更容易入味。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700031,'冬瓜虾仁蒸蛋','鸡蛋、虾仁、冬瓜、米饭，共 4 种食材，约 391 kcal。','午餐','中式',18,'中等',1,390.5,390.5,36.8,32.7,12.5,1.3,'[\"冬瓜切薄片铺碗底。\",\"鸡蛋加 1.5 倍温水打散，过筛倒入碗中。\",\"上锅蒸 8 分钟，放虾仁再蒸 3 分钟，配米饭。\"]','蛋液过筛能去气泡，蒸出来更滑。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700032,'三文鱼糙米波奇碗','糙米、三文鱼、黄瓜、胡萝卜、紫甘蓝、低钠酱油，共 6 种食材，约 343 kcal。','午餐','轻食',25,'中等',1,342.85,342.85,24.5,28.9,14.4,4,'[\"糙米蒸熟放凉。\",\"三文鱼煎至两面微焦，切块。\",\"蔬菜切丝，全部码在饭上，淋酱油。\"]','三文鱼煎到中间略粉红最好吃，别煎太老。',NULL,NULL,0,5,0,0,0,'增肌人群、控糖人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700033,'豆角焖面','面条、瘦猪里脊、芹菜、洋葱、橄榄油，共 5 种食材，约 321 kcal。','午餐','中式',30,'较难',1,320.95,320.95,22.6,31.3,11.4,2.8,'[\"肉切丝，芹菜切段。\",\"少油炒香洋葱与肉丝。\",\"下芹菜炒软，加水没过食材，铺上面条焖 8 分钟。\"]','面条铺在最上面不要翻动，靠蒸汽焖熟才不粘。',NULL,NULL,0,5,0,0,0,'增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700034,'鸡蛋炒饭配紫菜汤','米饭、鸡蛋、胡萝卜、青椒、海带，共 5 种食材，约 395 kcal。','午餐','中式',18,'中等',1,395.2,395.2,19.7,51.2,12.5,3.2,'[\"鸡蛋打散炒成蛋块盛出。\",\"下米饭炒散，加胡萝卜丁青椒丁。\",\"倒回鸡蛋翻匀，海带煮汤配食。\"]','米饭提前用手抓散，炒的时候更容易粒粒分明。',NULL,NULL,0,5,0,0,0,'减脂人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700035,'巴沙鱼柳配薯泥','巴沙鱼、土豆、低脂牛奶、西兰花、橄榄油，共 5 种食材，约 315 kcal。','午餐','西式',25,'中等',1,314.76,314.76,28.7,33.3,7.9,5.4,'[\"土豆蒸 15 分钟压成泥，加牛奶调匀。\",\"巴沙鱼两面煎 3 分钟。\",\"西兰花焯水，与薯泥一同装盘。\"]','薯泥加温牛奶更顺滑，冷牛奶会让土豆变粘。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700036,'毛豆鸡丁盖饭','米饭、鸡胸肉、毛豆、彩椒、橄榄油，共 5 种食材，约 461 kcal。','午餐','中式',22,'中等',1,461.46,461.46,44.1,43.9,11.7,5.4,'[\"鸡胸切丁用淀粉抓匀。\",\"毛豆煮 5 分钟去皮。\",\"少油炒鸡丁至变色，下毛豆彩椒翻炒，浇在饭上。\"]','毛豆和鸡丁都是高蛋白，这道菜蛋白约 35g。',NULL,NULL,0,5,0,0,0,'增肌人群、控糖人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700037,'藜麦三文鱼蔬菜饭','藜麦、三文鱼、菠菜、番茄、橄榄油，共 5 种食材，约 476 kcal。','午餐','轻食',25,'中等',1,476.16,476.16,29.9,44.5,20.2,6.9,'[\"藜麦煮 15 分钟沥干。\",\"三文鱼煎 3 分钟切块。\",\"菠菜焯水，与番茄一起拌匀。\"]','藜麦本身有微微坚果香，配三文鱼很搭。',NULL,NULL,0,5,0,0,0,'增肌人群、控糖人群','维持',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700038,'冬瓜排骨汤','瘦猪里脊、冬瓜、胡萝卜、米饭，共 4 种食材，约 306 kcal。','晚餐','中式',45,'较难',1,306.1,306.1,25.9,33.5,7.6,3.3,'[\"肉块焯水去血沫。\",\"加胡萝卜与水，大火烧开转小火炖 30 分钟。\",\"下冬瓜再炖 10 分钟，配米饭。\"]','冬瓜最后放，久炖会烂成泥。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700039,'蒜蓉西兰花','西兰花、蒜末、橄榄油、红薯，共 4 种食材，约 207 kcal。','晚餐','中式',12,'简单',1,207.21,207.21,7.3,38.3,4.9,8.4,'[\"西兰花掰小朵焯水 1 分钟。\",\"少油爆香蒜末。\",\"下西兰花大火快炒 2 分钟，红薯蒸熟同食。\"]','西兰花焯水后过凉水，颜色更翠绿。',NULL,NULL,0,5,0,0,0,'减脂人群、控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700040,'番茄牛腩汤','牛肉、番茄、洋葱、土豆，共 4 种食材，约 425 kcal。','晚餐','中式',60,'较难',1,425,425,35.3,27.9,20.9,5,'[\"牛肉切块焯水。\",\"番茄洋葱炒出汁，加牛肉与水炖 40 分钟。\",\"下土豆块再炖 15 分钟。\"]','番茄要炒到起沙，汤才够浓。',NULL,NULL,0,5,0,0,0,'增肌人群、控糖人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700041,'清炒小白菜配豆腐','小白菜、豆腐、橄榄油、糙米，共 4 种食材，约 224 kcal。','晚餐','中式',15,'中等',1,224.16,224.16,14.7,20.6,11.1,3.3,'[\"小白菜切段，豆腐切块。\",\"少油先煎豆腐至两面微黄。\",\"下小白菜快炒 2 分钟，配糙米饭。\"]','豆腐先煎再炒，不容易碎。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700042,'虾仁芦笋','虾仁、芦笋、彩椒、米饭，共 4 种食材，约 258 kcal。','晚餐','中式',15,'中等',1,257.9,257.9,32.2,31.9,0.9,4.4,'[\"虾仁去虾线，芦笋切段。\",\"少油炒虾仁至变色盛出。\",\"下芦笋彩椒炒 2 分钟，倒回虾仁调味。\"]','芦笋根部老的部分削去表皮再炒。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700043,'蘑菇豆腐汤配紫薯','蘑菇、豆腐、菠菜、紫薯，共 4 种食材，约 234 kcal。','晚餐','中式',20,'中等',1,233.8,233.8,18.3,31.2,7,7,'[\"蘑菇切片，豆腐切块。\",\"加水烧开，下蘑菇煮 5 分钟。\",\"放豆腐与菠菜再煮 3 分钟，紫薯蒸熟同食。\"]','蘑菇汤不用放味精，本身就很鲜。',NULL,NULL,0,5,0,0,0,'减脂人群、控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700044,'芹菜炒牛肉','芹菜、牛里脊、青椒、米饭、橄榄油，共 5 种食材，约 299 kcal。','晚餐','中式',18,'中等',1,298.76,298.76,24.2,29.8,8.9,3.3,'[\"牛里脊逆纹切片用淀粉抓匀。\",\"芹菜切段焯水 30 秒。\",\"快炒牛肉至变色，下芹菜青椒翻炒，配米饭。\"]','芹菜焯水能去掉涩味，也更容易炒断生。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700045,'鸡胸肉杂蔬汤','鸡胸肉、番茄、蘑菇、小白菜、玉米，共 5 种食材，约 287 kcal。','晚餐','中式',22,'中等',1,286.5,286.5,38.1,25,5.3,4.9,'[\"鸡胸切块用淀粉抓匀。\",\"番茄炒出汁加水烧开。\",\"下蘑菇玉米煮 6 分钟，放鸡肉与小白菜再煮 3 分钟。\"]','玉米当主食，这锅汤热量不到 300 kcal。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700046,'清蒸茄子','茄子、蒜末、低钠酱油、糙米，共 4 种食材，约 138 kcal。','晚餐','中式',20,'中等',1,138.33,138.33,4.8,30,1.1,3.8,'[\"茄子切长条上锅蒸 12 分钟。\",\"取出倒掉蒸出的水。\",\"淋酱油撒蒜末，配糙米饭。\"]','茄子蒸着吃几乎不吸油，是控脂期的好选择。',NULL,NULL,0,5,0,0,0,'减脂人群、控脂人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700047,'海带豆腐汤配馒头','海带、豆腐、小白菜、馒头，共 4 种食材，约 303 kcal。','晚餐','中式',22,'中等',1,303,303,18.4,44.2,8.1,3,'[\"海带提前泡发切丝。\",\"加水烧开，下海带煮 8 分钟。\",\"放豆腐与小白菜煮 3 分钟，配馒头。\"]','海带含碘高，甲状腺异常者需遵医嘱。',NULL,NULL,0,5,0,0,0,'减脂人群、控脂人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700048,'西葫芦虾仁','西葫芦、虾仁、鸡蛋、米饭，共 4 种食材，约 304 kcal。','晚餐','中式',15,'中等',1,303.55,303.55,33.1,28.1,6.9,2.1,'[\"西葫芦切片，鸡蛋炒散盛出。\",\"炒虾仁至变色。\",\"下西葫芦炒软，倒回鸡蛋翻匀，配米饭。\"]','西葫芦出水多，全程大火快炒。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700049,'土豆炖鸡肉','土豆、去皮鸡腿肉、胡萝卜、洋葱、低钠酱油，共 5 种食材，约 332 kcal。','晚餐','中式',35,'较难',1,331.58,331.58,24.5,37.3,9.1,5.9,'[\"鸡腿肉切块焯水。\",\"少油炒香洋葱，下鸡肉炒至微黄。\",\"加土豆胡萝卜与水炖 20 分钟，收汁调味。\"]','土豆当主食吃，这道菜不用再配米饭。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700050,'凉拌菠菜花生','菠菜、花生、蒜末、低钠酱油、红薯，共 5 种食材，约 230 kcal。','晚餐','中式',12,'简单',1,229.66,229.66,11.5,32.4,8.2,8.6,'[\"菠菜焯水 1 分钟过凉水。\",\"挤干水分切段。\",\"加花生、蒜末、酱油拌匀，红薯蒸熟同食。\"]','菠菜焯水后挤干，拌出来才不会出汤。',NULL,NULL,0,5,0,0,0,'控糖人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700051,'豆腐丸子汤','豆腐、鸡蛋清、胡萝卜、小白菜、荞麦面，共 5 种食材，约 228 kcal。','晚餐','中式',25,'中等',1,228.2,228.2,23.1,21.2,7.7,4.2,'[\"豆腐压碎与蛋清、胡萝卜末拌成馅。\",\"搓丸子下微沸水中定型。\",\"加白菜与荞麦面煮 6 分钟。\"]','丸子下锅时水保持微沸，大火会冲散。',NULL,NULL,0,5,0,0,0,'增肌人群、控糖人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700052,'菌菇鸡茸汤','菌菇、鸡胸肉、小白菜、南瓜，共 4 种食材，约 235 kcal。','晚餐','中式',22,'中等',1,235.2,235.2,37.4,14,4.3,4.6,'[\"菌菇撕成小朵，鸡胸剁成茸。\",\"加水烧开下菌菇煮 6 分钟。\",\"鸡肉茸分次下锅搅散，最后放小白菜。\"]','南瓜蒸熟压泥可另配，也可不加保持低热量。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700053,'番茄金枪鱼意面','面条、金枪鱼、番茄、洋葱、橄榄油，共 5 种食材，约 306 kcal。','晚餐','西式',20,'中等',1,306.36,306.36,29.9,32.7,6.1,3.2,'[\"面条煮 8 分钟捞出。\",\"番茄洋葱炒软出汁。\",\"下金枪鱼拌炒，浇在面上。\"]','金枪鱼选水浸款，脂肪比油浸少约 10g。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700054,'芦笋培根鸡胸卷','芦笋、鸡胸肉、彩椒、米饭、黑胡椒，共 5 种食材，约 325 kcal。','晚餐','西式',22,'中等',1,325.21,325.21,39.7,30.7,4.5,4.4,'[\"鸡胸切薄片，芦笋切段。\",\"用鸡胸片卷起芦笋段。\",\"平底锅少油煎至两面金黄，撒黑胡椒，配米饭。\"]','鸡胸片拍得薄一些，卷起来才服帖。',NULL,NULL,0,5,0,0,0,'减脂人群、增肌人群','增肌',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700055,'火龙果酸奶杯','无糖酸奶、火龙果，共 2 种食材，约 132 kcal。','加餐','轻食',4,'简单',1,131.6,131.6,5.7,19.1,4.4,1.6,'[\"火龙果切小丁。\",\"与酸奶拌匀即可。\"]','红心火龙果颜色更好看，热量差异不大。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700056,'开心果圣女果','开心果、番茄，共 2 种食材，约 102 kcal。','加餐','轻食',3,'简单',1,102.3,102.3,3.9,8,7,2.8,'[\"小番茄洗净。\",\"与开心果一同装碗。\"]','坚果配番茄，饱腹又不升糖太快。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700057,'鸡蛋黄瓜条','鸡蛋、黄瓜，共 2 种食材，约 103 kcal。','加餐','轻食',8,'简单',1,103.25,103.25,8.1,4.9,6,0.6,'[\"鸡蛋煮 8 分钟。\",\"黄瓜切条。\",\"一同装盘即可。\"]','不到 120 kcal，蛋白却有 8g。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700058,'豆浆香蕉','豆浆、香蕉，共 2 种食材，约 149 kcal。','加餐','中式',3,'简单',1,148.7,148.7,9.1,21.2,4.5,3.1,'[\"豆浆加热。\",\"配香蕉食用。\"]','运动后补充碳水与蛋白的简单组合。',NULL,NULL,0,5,0,0,0,'减脂人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
INSERT INTO `recipe` VALUES (700059,'猕猴桃核桃','猕猴桃、核桃，共 2 种食材，约 139 kcal。','加餐','轻食',3,'简单',1,139.48,139.48,2.9,16.4,8.3,3.8,'[\"猕猴桃切块。\",\"配核桃一同食用。\"]','核桃提供优质脂肪，猕猴桃补充维生素 C。',NULL,NULL,0,5,0,0,0,'均衡维持人群','减脂',1,'2026-11-02 18:17:07','2026-11-02 18:17:07');
