INSERT INTO `health_article` VALUES (2038627116093902854,'如何正确摄入蛋白质','摄入蛋白质的关键在于总量足够、来源优质、均匀分布。以下为科学且可操作的建议： 一、每天需要多少蛋白质？ 简易公式：推荐摄入量 = 体重(kg) × 1.0～1.5g 久坐人群：× 0.8～1.0g 健身/运动人群：× 1.2～1.7g 减脂','摄入蛋白质的关键在于总量足够、来源优质、均匀分布。以下为科学且可操作的建议：\n\n一、每天需要多少蛋白质？\n简易公式：推荐摄入量 = 体重(kg) × 1.0～1.5g\n\n久坐人群：× 0.8～1.0g\n\n健身/运动人群：× 1.2～1.7g\n\n减脂期或老年人：× 1.2～1.5g\n\n举例：体重70kg的健身者，每日约需84～105g蛋白质。\n\n二、优选蛋白质来源\n类别	优质来源	每100g约含蛋白\n动物性	鸡胸肉、瘦牛肉、鱼虾、鸡蛋、牛奶、希腊酸奶	20～30g\n植物性	豆腐、豆豉、鹰嘴豆、扁豆、藜麦	8～20g\n关键点：优先选择完整蛋白（含全部必需氨基酸），植物蛋白可搭配谷物+豆类互补。\n\n三、分餐摄入更高效\n每餐20～40g 比单餐大量摄入利用率更高。\n示例分配（84g/日）：\n\n早餐：2个鸡蛋（12g）+ 250ml牛奶（8g）= 20g\n\n午餐：150g鸡胸肉（35g）= 35g\n\n晚餐：150g豆腐（12g）+ 半碗藜麦（4g）= 16g\n\n加餐：一份希腊酸奶（10g）= 10g\n\n四、特殊人群注意事项\n健身增肌：训练后1小时内补充20～40g快吸收蛋白（如乳清蛋白粉）\n\n减脂人群：每公斤体重1.2～1.5g，可抑制饥饿感、减少肌肉流失\n\n肾病患者：需严格遵医嘱，通常需低蛋白饮食（0.6～0.8g/kg）\n\n素食者：每餐搭配豆类+谷物（如红豆米饭），或补充大豆蛋白粉\n\n五、避免两个常见误区\n❌ 只靠蛋白粉：优先从天然食物获取，蛋白粉仅作补充\n❌ 单餐超量：一顿吃100g蛋白，大部分会转化为热量或增加肾脏负担\n\n六、简便自查法\n用手掌大小估算每餐蛋白质量：\n\n肉/鱼：一掌心大小、手指厚度 → 约20～25g\n\n鸡蛋：2个 → 约12g\n\n豆腐：一拳头 → 约10～12g\n\n如果你有具体的健康目标（如增肌、减脂、孕期）或饮食限制（如素食、低脂），可以告诉我，我会给出更针对性的建议。','饮食指南','','健康管理编辑部',NULL,'增肌塑形',3,0,0,'2026-04-12',1,'2026-04-12 22:59:53','2026-04-12 22:59:53');
